import{r as e}from"./rolldown-runtime-S-ySWqyJ.js";import{i as t,r as n}from"./framework-CXnKph_e.js";var r=e(t(),1),i=JSON.parse(`[{"url":"/flu","title":"Influenza: What you need to know","category":"Patient resources","text":"Patient Guide to Influenza - Gennady Gelman A clear, practical guide to influenza prevention, vaccination, treatment, medication safety, and when to get help. 02 Inside your body Why the flu makes you feel so awful. Some of it is the virus. Most of it is your immune system doing its job. 01 The virus arrives About one to four days after exposure — two, on average — influenza takes hold in the lining of your nose, throat, and airways. That&apos;s where the cough, sore throat, congestion, and chest discomfort come from. 02 Your immune system sounds the alarm Immune cells detect the virus and release chemical signals called cytokines — a kind of internal alarm bell. They rally the rest of your immune system into action, and that same alarm is what triggers fever, aches, fatigue, and the feeling that you&apos;ve been hit by a truck. The discomfort isn&apos;t a side effect of the war. It&apos;s part of the strategy. 03 Your body changes priorities Fever turns up your body&apos;s internal thermostat on purpose: influenza replicates less efficiently at higher temperatures, and your immune cells work better too. Shivering is how you generate the heat to get there fast. Fatigue works the same way — it pulls energy away from everything else so your body can spend it all on defense. The short version Listen to your body. If you are tired, sleep. If you are thirsty, drink. If you are cold, get under a blanket. If you are sick, stop trying to power through it. Your immune system has been dealing with viruses much longer than you have been answering email. 04 What actually helps Comfort counts. For most otherwise healthy people, influenza gets better with time and supportive care. The basic prescription is surprisingly boring. Sleep Sleep is not wasted time when you are sick. Your body is mounting an immune response. Give it the opportunity to work. Drink Water, tea, broth, ice chips, and oral rehydration drinks all count. Small, frequent sips can be easier when you feel nauseated. Use saline Warm salt-water gargles can soothe the throat. Nasal saline can loosen mucus. Use safe water for nasal irrigation. Treat discomfort You do not have to chase a modest fever if you are comfortable. But you do not earn bonus points for suffering. Medication reality check Over the counter does not mean risk-free. Acetaminophen can be dangerous in excessive doses. Ibuprofen and other NSAIDs can cause bleeding, affect the kidneys, and interact with medicines. Many combination cold products already contain acetaminophen. Read every label. use client USA MA https://data.cdc.gov/resource/ua7e-t2fy.json?%24select=weekendingdate%2Cjurisdiction%2Ctotalconfflunewadmper100k&%24where=jurisdiction%20in(%27USA%27%2C%27MA%27)&%24order=weekendingdate%20DESC&%24limit=48 en-US short numeric en-US long numeric numeric loading ready error loading no-store CDC data request failed ready AbortError error USA MA L M Current CDC flu activity Live weekly hospitalization data loading Loading the latest CDC data… error The CDC data could not be loaded right now. Open CDC FluView instead. ready Weekly laboratory-confirmed influenza hospital admissions Rate per 100,000 people Latest week ending United States — Massachusetts — start end middle CDC data are preliminary and updated weekly. A low hospitalization rate does not mean influenza is absent. Source: CDC National Healthcare Safety Network. Open the full CDC FluView report. When to get help Call early if you are high-risk. Get urgent help for warning signs. Contact your clinician promptly if you are pregnant, older, immunocompromised, have important chronic medical conditions, are very sick, cannot stay hydrated, or simply feel that something is wrong. Review CDC warning signs ↗ use client urgent call choice active choice ✓ Step 1 Do you have any of the following? choice danger-choice active choice danger-choice ✓ choice no-warning-choice active choice no-warning-choice ✓ None of these Stop. Seek urgent medical care now. The warning sign you selected can occur with serious influenza or another urgent condition. Do not continue through this tool or wait to see whether it gets better. Get medical help now. urgent Start with warning signs Select any warning sign that is present. If none apply, choose “None of these” to continue. Pregnant Pregnancy and medication safety Before taking any prescription or over-the-counter medicine for flu symptoms, check with your PCP or OB clinician unless they have already told you what is safe. Even familiar medicines may not be safe during pregnancy. Ibuprofen and other NSAIDs can be harmful, especially at 20 weeks or later, and some combination cold and flu products contain them. call Symptoms began within 48 hours Symptoms began within 48 hours Call your clinician early Antiviral treatment works best when started early and is especially important for people at higher risk of complications. Treatment can still help later when illness is severe or risk is high. call Antivirals work best early If your symptoms began within the past 48 hours and you are considering antiviral treatment, contact your clinician soon. The benefit is generally greatest when treatment starts early. call Fever or chills Body aches For fever and body aches Rest and drink fluids. Because you selected pregnancy, check with your PCP or OB clinician before taking medicine for fever or aches unless they have already given you specific instructions. Rest, drink fluids, and treat discomfort rather than chasing a number. Acetaminophen or ibuprofen may help if they are safe with your health conditions and other medicines. Check combination cold products before adding either one. Stuffy nose Runny nose or postnasal drip For congestion and drainage Try nasal saline first. Oxymetazoline can provide short-term relief for some people, but generally should not be used for more than three days because it can cause rebound congestion. Sore throat For a sore throat Warm drinks, fluids, and salt-water gargles can soothe irritated tissue. Comfort matters even when a remedy does not kill the virus. Cough For cough Consider whether nasal drainage is triggering the cough. Saline, fluids, and gently clearing nasal secretions may help. A cough also clears mucus, so turning off every cough is not always the goal. Fatigue Poor appetite or nausea Trouble drinking enough fluids Protect your energy and hydration Sleep. Take small, frequent sips if a full glass feels difficult. Water, tea, broth, ice chips, and oral rehydration drinks are all reasonable options. Choose what you are dealing with Select symptoms and risk factors. Your general comfort and next-step suggestions will appear here. Interactive tool Build your flu comfort plan. If you do get the flu (or other viral respiratory illness), use the tool below to manage symptoms, and decide when to reach out for help. Does any additional risk apply? Step 2 What symptoms are you dealing with? Step 3 plan-results urgent-stop plan-results Your suggestions result Reset selections General education only. This is not a diagnosis or individualized medical advice. Medication safety depends on age, pregnancy, health conditions, kidney and liver function, allergies, and other medicines. Influenza What I want my patients to know about prevention, treatment, and when to get help. Build your flu comfort plan ↓ Understand the flu 01 Influenza is a serious virus. In 1918, an H1N1 influenza virus caused one of the deadliest pandemics in recorded history. An estimated 500 million people became infected , roughly one-third of the world&apos;s population. At least 50 million people died . It is difficult to overstate how devastating a loss that was, especially coming on the heels of World War I, which had already killed millions of people and profoundly disrupted societies around the world. And those numbers become even more staggering when you consider this: There were only about 1.8 billion people on Earth. World population over the long run. Source: Max Roser, Our World in Data . CC BY 4.0 . Humanity took thousands of years to reach a population of roughly 1.8 billion. Then, in barely more than a century, we grew to more than 8 billion. Now return to that 1918 number: 500 million infections. One out of every three humans alive. Read the CDC history of the 1918 pandemic. Today is very different We have vaccines, antiviral medications, antibiotics for secondary bacterial infections, modern hospitals, and intensive care. But influenza has not become harmless. Influenza affects more than just your lungs. In a 2018 study published in the New England Journal of Medicine, hospital admissions for heart attack were about six times as frequent during the first seven days after laboratory-confirmed influenza as during control periods before and after the infection. Read the heart attack study. Influenza also causes thousands of deaths each year. Since 2010, the CDC estimates that annual influenza deaths in the United States have ranged from about 6,300 to 52,000. Track influenza in Massachusetts. View the CDC FluView tracker. 05 Medicines: what helps and what does not Know what you are treating and why. Antivirals Most important for higher-risk patients Antiviral treatment is recommended promptly for people who are hospitalized, very sick, or at higher risk of serious complications. People at higher risk include pregnant people, adults 65 and older, young children, people with certain chronic conditions, and people who are immunocompromised. If that describes you, call early. Do not wait for illness to become severe. For otherwise healthy people with mild, uncomplicated influenza, most do not need an antiviral. Medicine How it is taken What to know Oseltamivir (Tamiflu) Pill or liquid, usually twice daily for five days The usual first choice for most patients and the preferred option during pregnancy and for severe or hospitalized illness. Baloxavir A single oral dose An option for uncomplicated influenza when started within 48 hours. It is not recommended during pregnancy or breastfeeding, or for severe, progressive, or hospitalized illness. Convenient, but coverage varies and it may cost more than generic oseltamivir. A lower-cost generic was recently approved but may not yet be widely available. Zanamivir Inhaled powder, usually twice daily for five days Not recommended for people with asthma, COPD, or other airway disease because it can cause bronchospasm. Peramivir A single intravenous dose given by a clinician May be useful when oral medicine cannot be taken or absorbed. Evidence for severe influenza is limited. When started within the first one or two days, oseltamivir may make symptoms milder and shorten illness by about a day on average. That can be worthwhile for some people, but it is not a necessary treatment for everyone. For severe, progressive, or hospitalized illness, treatment may still help even when more than 48 hours have passed. CDC antiviral guidance ↗ Antibiotics Not for the influenza virus Antibiotics work against bacteria. Influenza is a virus and does not have the bacterial structures or processes that antibiotics target. So the antibiotics don&apos;t apply here. Some antibiotics, including macrolides such as azithromycin, have anti-inflammatory effects in certain settings and may have made you feel better in the past. That does not make them a treatment for uncomplicated influenza and does not justify taking them “just in case.” The side effects and antibiotic resistance are real, while the influenza virus remains untreated. That said, influenza can set the stage for a secondary bacterial infection, especially pneumonia. If you start to improve and then develop a new fever, worsening cough, shortness of breath, chest pain, or a major decline, call us. That is a reason to be examined. Oxymetazoline nasal spray Works, but keep it short It can provide excellent short-term relief from severe congestion. Repeated use for too long can cause rebound congestion. Think short term, generally no more than three days. For ongoing congestion, saline is much friendlier. Antihistamines Read the ingredients Older antihistamines in many nighttime products can cause sedation, confusion, falls, dry mouth, constipation, and urinary retention. Those risks matter especially in older adults. Guaifenesin Fine if it helps Guaifenesin is intended to make secretions easier to clear. Benefits may be modest and it can upset the stomach. Hydration matters too. Benzonatate I am less enthusiastic Evidence for acute cough is limited, and cough helps clear secretions. Accidental ingestion can cause severe toxicity in children. Often the better question is why you are coughing and whether postnasal drainage is driving it. FDA safety information ↗ 06 Home remedies and myths Feeling better is a valid outcome. I like home remedies. I just distinguish between “this makes me feel better” and “this kills influenza.” Those are very different claims. If warm tea soothes your throat, drink it. If your grandmother&apos;s soup makes you feel human again, eat the soup. If honey, ginger, apples, or a family tradition helps you rest and recover, and it is safe for you, I am not going to demand a randomized trial before you enjoy it. Not everything that helps has to kill the virus. Sometimes feeling better is enough. Things I would not spend much money on Oscillococcinum: good evidence that it meaningfully prevents or treats influenza is lacking. Vitamin C after you are sick: fine in your diet, but not a proven influenza treatment. Zinc for influenza: discussed more for the common cold and not established as an effective flu treatment. Vitamin megadoses: correct real deficiencies. More is not automatically better. Influenza: The Flu Patient education by Gennady Gelman, MD CDC Influenza WHO Global Influenza Programme Back to top ↑ Educational information only. Last reviewed August 2026. use client serious-virus About the Flu inside-your-body Inside Your Body prevention Prevention vaccine-advisor What's the right vaccine for me? treatment Treatment flu-plan Custom symptom plan emergency Warning Signs scroll resize scroll resize (prefers-reduced-motion: reduce) auto smooth GG Gennady Gelman, MD nav-alert is-active vaccine-advisor vaccine-advisor location Search If you remember nothing else 01 Get vaccinated. For most people, September or October is a good target. Later is still better than never. 02 If you are sick, stay home. Do not donate your influenza to the community. 03 Listen to your body. Sleep. Drink. Rest. Get comfortable. 04 Do not throw medicines at every symptom. Understand what you are treating and why. 05 If you are high-risk, call early. Antiviral treatment is most useful when we do not wait. 06 Warning signs mean get help. Trouble breathing, chest pain, confusion, dehydration, or rapid worsening should not wait. Your body is not doing nothing while you lie in bed feeling miserable. It is running an extraordinarily sophisticated defense operation. 03 Flu season and vaccination Vaccination is the best tool we have against influenza. This year&apos;s options The CDC recommends that everyone 6 months and older get a flu vaccine every year, with rare exceptions. This year brings more options than ever: standard-dose, high-dose, and live attenuated nasal spray vaccines, plus a newly FDA-approved mRNA vaccine for adults 50 and older. Children between 6 months and 8 years old who have not previously received at least two flu vaccine doses need two doses this season, given at least four weeks apart. The previous doses do not need to have been given during the same or consecutive seasons. After that, one dose a year is enough. Type of vaccine Who it is for Pros and cons Standard-dose Most people 6 months and older The most widely used option, with extensive experience across age groups. Cell-based standard-dose formulations and a separate recombinant vaccine are egg-free, although specific age approvals vary. Egg allergy, even if severe, is not a reason to avoid any flu vaccine. High-dose Adults 65 and older Contains extra antigen to produce a stronger immune response in older immune systems. It can cause more soreness or achiness than a standard-dose vaccine. CDC also preferentially recommends adjuvanted or recombinant vaccines for this age group. Live attenuated nasal spray Healthy, non-pregnant people ages 2 to 49 No needle, which can make vaccination easier for children and others who dislike injections. It uses weakened live virus, so it is not an option during pregnancy or immunocompromise. Asthma and certain chronic conditions may also make another vaccine a better choice. mRNA Adults 50 and older Newly FDA-approved technology that may be easier to update quickly as influenza strains change. It is still building a real-world track record. For adults 65 and older, CDC&apos;s established preferred options are high-dose, adjuvanted, or recombinant vaccines. We do not always get every detail right. Sometimes the strains chosen months in advance turn out to be an imperfect match, but that is a long way from a random guess. How strains are chosen Influenza spreads more efficiently in cooler, drier conditions. Then people add another ingredient: we go inside. Windows close, schools are in session, and we spend more time breathing the same air. When it is summer in New England, it is winter in the Southern Hemisphere. Their flu season occurs during our summer. That turns out to be medically useful. Laboratories around the world collect and study circulating influenza viruses. Scientists track which strains are spreading and how they are changing. The World Health Organization reviews the data and issues separate vaccine recommendations for the Northern and Southern Hemispheres. Want to nerd out? See how WHO chooses vaccine strains ↗ Vaccine safety The standard flu shot cannot give you influenza. It does not contain live influenza virus capable of causing infection or replicating in your body. I think of it this way. The scene is an old Western town. The sheriff is putting up wanted signs. The outlaw is the flu. The flu is the outlaw. Vaccination gives your immune system the wanted poster. The standard flu shot contains enough influenza antigen for your immune system to study the poster and build antibodies and immune memory, without ever meeting the real outlaw. Full protection takes about two weeks to develop. Some people may feel achy or run a low fever after the shot. That is the town running a drill, the same kind of immune response your body uses against a real infection. It does not mean that the vaccine has infected your airways. The drill is not the actual robbery. That is the whole point of the drill. If the real outlaw ever does ride into town, your immune system already has antibodies and white blood cells watching for it, ready to recognize it on sight and respond before it can cause as much trouble. When to get vaccinated For most adults, September or October is the sweet spot. Vaccinating too early can mean more waning by late winter. Waiting too long risks letting influenza arrive first. If October has passed, get vaccinated anyway while influenza is still circulating. Current CDC vaccination recommendations · The 2026 to 2027 flu season · FDA information on the mRNA flu vaccine use client under-6-months 6-to-23-months 2-to-12 13-to-17 18-to-49 50-to-64 65-plus yes no pregnant high-risk asthma egg nasal under-6-months Under 6 months 6-to-23-months 6 to 23 months 2-to-12 2 to 12 years 13-to-17 13 to 17 years 18-to-49 18 to 49 years 50-to-64 50 to 64 years 65-plus 65 years or older pregnant Pregnant high-risk Weakened immune system or high-risk condition, such as HIV, cancer treatment, transplant medicines, heart or lung disease, or diabetes asthma Asthma or recent wheezing egg Egg allergy nasal Strongly prefer a nasal spray or want to avoid a needle 13-to-17 18-to-49 50-to-64 pregnant pregnant 13-to-17 18-to-49 50-to-64 yes Talk with your physician Do not choose a flu vaccine using this tool. Your physician should review what happened and help determine whether and how you should be vaccinated. Guillain-Barré syndrome within 6 weeks after a flu vaccine is a precaution. A severe reaction may require choosing a different formulation or vaccination setting. Start with question 1 Answer the safety question first. If the answer is no, the rest of the advisor will open. Choose an age group Choose an age group in question 2 to see the appropriate vaccine options. under-6-months No flu vaccine is licensed yet Infants younger than 6 months cannot receive a flu vaccine. Vaccinating parents, caregivers, and household members helps create a circle of protection. Plan the infant's first flu vaccine once they are 6 months old. pregnant high-risk asthma egg Egg allergy does not change the recommendation. Any otherwise appropriate flu vaccine may be used, including egg-based vaccines. pregnant During pregnancy, choose an injected vaccine. Do not use the live nasal spray vaccine. high-risk An injected vaccine is the straightforward choice for people who are immunocompromised or have high-risk chronic conditions. asthma An injected vaccine avoids the nasal spray restrictions and precautions associated with asthma and recent wheezing. nasal The nasal spray is not the right fit with the health information selected above. nasal 6-to-23-months 50-to-64 65-plus The nasal spray is licensed only for people ages 2 through 49. Choose an age-appropriate injected flu vaccine For most people, there is no single best brand. The important thing is to receive an age-appropriate vaccine this season. 6-to-23-months Choose an age-appropriate flu shot Children in this age group should receive an injectable vaccine approved for their age. Depending on prior flu vaccination, two doses at least 4 weeks apart may be needed. 2-to-12 13-to-17 nasal The nasal spray is a reasonable option Choose an age-appropriate flu shot Healthy, non-pregnant people ages 2 through 17 may receive either an age-appropriate flu shot or the nasal spray. There is no general preference between them. An age-appropriate injected vaccine is the most straightforward choice based on the selections above. 2-to-12 Children through age 8 may need 2 doses this season, depending on their previous flu vaccination history. 18-to-49 nasal The nasal spray is a reasonable option Choose an age-appropriate flu shot Healthy, non-pregnant adults ages 18 through 49 may receive an age-appropriate flu shot or the nasal spray. There is no general preference between them. Standard-dose, cell-based, or recombinant injected vaccines are reasonable age-appropriate options. 50-to-64 Choose an age-appropriate injected vaccine Standard-dose, cell-based, and recombinant vaccines are options for adults 50 through 64. The new mRNA vaccine is FDA-approved for adults 50 and older, but current CDC guidance and local availability should be confirmed before choosing it. 65-plus Prefer an enhanced or recombinant vaccine CDC preferentially recommends a high-dose, adjuvanted, or recombinant flu vaccine for adults 65 and older. If none is available, get any other age-appropriate flu vaccine rather than waiting. The new mRNA vaccine is FDA-approved for adults 50 and older, but it is not one of CDC's established preferred options for adults 65 and older. Quick decision guide Which flu vaccine should I get? Open the vaccine advisor 1. Have you ever had either of these? Guillain-Barré syndrome within 6 weeks after a flu vaccine, or a severe allergic reaction to a flu vaccine or one of its ingredients. yes no vaccine-option active vaccine-option yes Yes No no 2. How old is the person being vaccinated? vaccine-option active vaccine-option no under-6-months 3. Any special circumstances or preferences? vaccine-option active vaccine-option ✓ yes vaccine-answer alert vaccine-answer Best fit yes Where to get vaccinated ↗ CDC vaccine details ↗ yes Contact your physician before receiving another flu vaccine. Call ahead to confirm that the location has the specific formulation you want. General education only. Final eligibility is confirmed by the vaccinating clinician or pharmacist."},{"url":"/medicolalia","title":"Medicolalia","category":"Explore","text":"Medicolalia Essays - Gennady Gelman Radically examining medical terminology. Essays on the roots and meanings of medical words. GG Gennady Gelman, MD Home Words & medicine Medicolalia Radically examining medical terminology. No. 2 · Syndrome Things That Run Together Read the post ↗ No. 1 · Migraine Migraines: The Headache Is Only Half the Story Read the post ↗ © Gennady Gelman"},{"url":"/","title":"Home","category":"Explore","text":"Clinical Tools and Health Resources - Gennady Gelman GG Gennady Gelman, MD Medicolalia Contact Search Gennady Gelman, MD Useful tools for clearer decisions. Clinical decision support, patient guidance, professional references, and a few ideas worth exploring. Explore Choose a direction Decision support Clinical Tools Browser-based tools for risk adjustment, cardiovascular prevention, lab interpretation, and pediatric immunizations. View all tools ↗ For patients Patient Resources Approachable guidance for healthier eating, movement, seasonal illness, useful apps, and everyday decisions. Explore resources ↗ For students & colleagues Professional Resources Clinical references, calculators, AI tools, Epic essentials, guidelines, and practical resources for learners and peers. Open the library ↗ Ideas & experiments Kiloday A rational alternative to birthdays: calculate the thousand-day milestones that divide a life in base ten. Read and calculate ↗ Words & medicine Medicolalia Radically examining medical terminology, one word and one clinical story at a time. Read the series ↗ © Gennady Gelman me@gennadygelman.com"},{"url":"/patients/apps","title":"Recommended health apps","category":"Patient resources","text":"Health and Wellness Apps - Gennady Gelman MyChart Your health record Message your care team, review results, manage appointments, and—when enabled by your health system—enter home blood pressure or glucose readings in Track My Health. https://apps.apple.com/us/app/mychart/id382952264 https://play.google.com/store/apps/details?id=epic.mychart.android Some health systems use their own branded MyChart app. Dr. Greger’s Daily Dozen Plant-forward nutrition A simple checklist of foods and activities emphasized by NutritionFacts.org and the books How Not to Die and How Not to Diet. https://apps.apple.com/us/app/dr-gregers-daily-dozen/id1060700802 https://play.google.com/store/apps/details?id=org.nutritionfacts.dailydozen Insomnia Coach Sleep · insomnia self-care A free VA app with a guided weekly training plan, sleep diary, and practical tools based on cognitive behavioral therapy for insomnia (CBT-I). https://apps.apple.com/us/app/insomnia-coach/id1341944736 https://play.google.com/store/apps/details?id=gov.va.mobilehealth.ncptsd.insomniacoach Can be used on your own or alongside professional care; it does not replace evaluation or treatment for sleep problems. CDC Milestone Tracker Child development Track developmental milestones from 2 months through age 5 and learn when to discuss a concern with your child’s clinician. https://apps.apple.com/us/app/cdcs-milestone-tracker/id1232718688 https://play.google.com/store/apps/details?id=gov.cdc.ncbddd.actearly.milestones MyFitnessPal Food tracking Track calories, nutrients, meals, and activity when structured self-monitoring would be useful. https://apps.apple.com/us/app/myfitnesspal-calorie-counter/id341232718 https://play.google.com/store/apps/details?id=com.myfitnesspal.android Tracking is not helpful for everyone, particularly with a history of disordered eating. Fastic Eating-window timer An intermittent-fasting timer that can help structure eating windows and build consistency. https://apps.apple.com/us/app/fastic-weight-loss-fasting/id1459260306 https://play.google.com/store/apps/details?id=de.fastic.app Discuss fasting first if you are pregnant, have an eating-disorder history, or use glucose-lowering medication. Fooducate Food labels Scan foods, review ingredients, and compare alternatives while learning how packaged foods differ. https://apps.apple.com/us/app/fooducate-nutrition-coach/id398436747 https://play.google.com/store/apps/details?id=com.fooducate.nutritionapp Flo Cycle tracking Track periods, symptoms, ovulation estimates, pregnancy, and perimenopause patterns. https://apps.apple.com/us/app/flo-cycle-period-tracker/id1038369065 https://play.google.com/store/apps/details?id=org.iggymedia.periodtracker Cycle predictions are estimates. Review privacy settings before entering sensitive information. Medisafe Medication reminders Set medication schedules, refill reminders, and optional family-support notifications. https://apps.apple.com/us/app/medisafe-medication-management/id573916946 https://play.google.com/store/apps/details?id=com.medisafe.android.client Bearable Symptoms & patterns Track symptoms alongside sleep, stress, habits, and medications to identify patterns worth discussing at a follow-up visit. https://apps.apple.com/us/app/bearable-symptom-tracker/id1482581097 https://play.google.com/store/apps/details?id=com.bearable Correlations in an app can suggest questions; they do not prove a cause. Pomodoro timer Focus & breaks Use 25-minute focus intervals with planned breaks. Any simple timer works; you do not need a subscription. https://apps.apple.com/us/search?term=pomodoro%20timer https://play.google.com/store/search?q=pomodoro%20timer&c=apps This is a method, not a specific endorsed app. Limit screen time Use Screen Time on Apple devices or Digital Wellbeing on Android to see patterns and set intentional limits. https://support.apple.com/en-us/108806 https://support.google.com/android/answer/9346420 Reduce evening blue light Schedule Night Shift on Apple devices or Night Light on Android as part of a broader wind-down routine. https://support.apple.com/en-us/118583 https://support.google.com/pixelphone/answer/7169926 Update emergency information Add medical conditions, medications, allergies, and emergency contacts that can be viewed while your phone is locked. https://support.apple.com/en-us/105072 https://support.google.com/android/answer/9319337 GG Gennady Gelman, MD ← Patient resources Search Apps I recommend to patients Useful tools, not more digital clutter. Choose an app only when it solves a specific problem. You do not need to download everything on this page. 0 note Download for iPhone / iPad ↗ Get it on Android ↗ One update to the original list Start Simple with MyPlate has been retired. The USDA app is no longer available on Google Play, so I do not recommend downloading an unofficial copy. Use the current MyPlate.gov website ↗ for its plate-based nutrition guidance. Already on your phone Built-in tools Apple instructions ↗ Android instructions ↗ Privacy matters Health apps are not your medical record. Before entering reproductive, symptom, medication, or mental-health information, review the app’s privacy settings and collect only what will genuinely help you. Do not rely on an app for emergencies or urgent medical advice. © Gennady Gelman me@gennadygelman.com"},{"url":"/patients/books/how-not-to-die","title":"How Not to Die","category":"Books","text":"How Not to Die Book Summary - Gennady Gelman How Not to Die Michael Greger, MD Nutrition · prevention Michael Greger makes an energetic case that eating more whole plant foods can reduce chronic-disease risk. Its practical strength is the Daily Dozen framework and its emphasis on dietary patterns rather than supplements or miracle foods. Many leading chronic diseases are influenced by modifiable behaviors. Vegetables, fruits, legumes, whole grains, nuts, and seeds deserve a larger place in most diets. A repeatable checklist can make an abstract goal like ‘eat healthier’ more concrete. Add one serving of beans or lentils most days. Make half the plate vegetables or fruit when practical. Replace one refined or animal-based food with a minimally processed plant food at a time. The book is advocacy-oriented and sometimes presents associations as more certain than they are. A healthy diet need not be perfectly vegan to produce meaningful benefit. Food supports health but does not replace indicated medicines, screening, or treatment. Which Daily Dozen items fit my culture, budget, and preferences? Do I need B12 or another supplement if I eat mostly plants? Which single food substitution would have the highest value for me?"},{"url":"/patients/books/how-not-to-diet","title":"How Not to Diet","category":"Books","text":"How Not to Diet Book Summary - Gennady Gelman How Not to Diet Michael Greger, MD Nutrition · weight This book collects research on satiety, energy density, fiber, food quality, and habits. Its central message is that a sustainable eating pattern matters more than a branded short-term diet. Foods with more water and fiber can provide greater fullness for fewer calories. Environment and defaults often shape eating more powerfully than motivation alone. Small habits that can be repeated are more useful than dramatic plans that cannot be maintained. Start meals with vegetables, soup, or another fiber-rich food. Keep convenient healthy foods visible and ready to eat. Track one behavior—such as sugary drinks or late-night eating—rather than trying to optimize everything. The book contains many individual tactics supported by evidence of uneven quality. No single food or hack overrides total intake, biology, medicines, sleep, and social conditions. Weight is only one health measure; strength, function, blood pressure, glucose, and well-being also matter. Which habit is most likely driving excess intake for me? Would a dietitian or structured program help? Should medication or metabolic surgery be part of the conversation?"},{"url":"/patients/books","title":"Patient bookshelf","category":"Books","text":"Patient Book Summaries - Gennady Gelman 01 the-obesity-code 9781771641258 The Obesity Code Jason Fung, MD Metabolic health · fasting A clear, provocative framework for understanding insulin, meal timing, and why weight regulation is more complicated than simply counting calories. Best used as a starting point for discussion; its insulin-centered explanation is more confident than the total evidence warrants. mint 02 why-we-get-sick 9781953295774 Why We Get Sick Benjamin Bikman, PhD Insulin resistance · metabolic health An accessible explanation of insulin resistance, why it matters, and how food, activity, sleep, and body composition influence metabolic health. Insulin resistance is important, but it is not a single explanation for every chronic disease or every case of obesity; several causal pathways reinforce one another. blue 03 how-not-to-die 9781250066114 How Not to Die Michael Greger, MD Nutrition · prevention An energetic tour of the relationship between food patterns and chronic disease, with a strong case for eating more whole plant foods. It is advocacy as well as education. Focus on the practical direction—not every causal claim or superlative. red 04 how-not-to-diet 9781250199225 How Not to Diet Michael Greger, MD Nutrition · weight A wide-ranging collection of strategies for satiety, food quality, and sustainable weight management without centering a commercial diet plan. The most useful lesson is the overall eating pattern; individual studies and tactics vary substantially in strength. green 05 why-we-sleep 9781501144318 Why We Sleep Matthew Walker, PhD Sleep · performance A compelling explanation of why sleep matters for memory, mood, metabolism, immunity, safety, and long-term health. Some dramatic statistics in the book have been disputed, but the central case for protecting sleep remains sound. night 06 staring-at-the-sun 9780787996680 Staring at the Sun Irvin D. Yalom, MD Mortality · meaning A humane, psychologically rich book about death anxiety and how confronting mortality can help us live with greater presence and intention. This is reflective reading, not a treatment manual—and may feel intense during acute grief or severe anxiety. gold 07–08 the-new-menopause 9780593796252 The New Menopause and The New Perimenopause Mary Claire Haver, MD Perimenopause · menopause · midlife health Two complementary guides to hormonal change: The New Perimenopause explores the transition years, while The New Menopause takes a broader look at menopause and midlife health. Both help you understand symptoms and prepare for conversations about care. Symptoms deserve attention, but not every new symptom is hormonal. Treatment should reflect your health history and preferences; hormone therapy is one option, not a universal prescription. red The New Perimenopause the-new-perimenopause /books/the-new-perimenopause.jpg GG Gennady Gelman, MD ← Patient resources Search Books I recommend to patients Eight books worth thinking with. These are conversation starters—not sacred texts. Each offers a useful lens, and each should be read with judgment rather than treated as a personalized prescription. companion by Read with context companion The New Menopause summary → The New Perimenopause summary → Read the patient summary → Before changing your care Bring the idea—not just the book—to your clinician. Nutrition, fasting, sleep, weight, mental health, and hormone advice can interact with medications and medical conditions. Discuss major changes with a healthcare professional who knows your history. © Gennady Gelman me@gennadygelman.com"},{"url":"/patients/books/staring-at-the-sun","title":"Staring at the Sun","category":"Books","text":"Staring at the Sun Book Summary - Gennady Gelman Staring at the Sun Irvin D. Yalom, MD Mortality · meaning Psychiatrist Irvin Yalom explores death anxiety with warmth and clinical wisdom. His central proposal is not that we eliminate fear, but that confronting finitude can clarify values, deepen relationships, and awaken us to life. Death anxiety can appear indirectly as worry, avoidance, regret, or a sense of unlived life. Connection and the influence we leave in others—what Yalom calls rippling—can counter isolation. Awareness of limited time can help us choose more deliberately and postpone less. Name one regret you can still act on. Have one conversation you have been postponing. Ask what you would change if you were protecting your limited time more honestly. This is reflective reading, not a workbook or treatment protocol. It may intensify distress during acute grief, panic, severe depression, or a new life-threatening diagnosis. Professional support is appropriate when death anxiety becomes intrusive or disabling. Is fear of death shaping a current decision or avoidance? What relationships or contributions give my life continuity? Would therapy help me approach this safely and constructively?"},{"url":"/patients/books/the-new-menopause","title":"The New Menopause","category":"Books","text":"The New Menopause Book Summary - Gennady Gelman The New Menopause Menopause · midlife health Mary Claire Haver introduces the changes associated with menopause and encourages women to seek informed, individualized care. This overview highlights the book’s themes; the practical care points below are general patient education. Mary Claire Haver, MD Menopause can affect quality of life, including sleep and sexual comfort. The book encourages informed conversations about symptoms and treatment choices. Write down your most bothersome symptoms and how they affect your day. Ask about hormonal and nonhormonal options, including their benefits and risks. A book cannot determine whether a treatment is appropriate for your health history. Do not start or change hormones or supplements without discussing them with your clinician. Which options fit my symptoms and medical history? How will we assess benefit and decide whether to adjust treatment? label Publisher’s book overview url https://www.penguinrandomhouse.com/books/738539/the-new-menopause-by-mary-claire-haver-md/ label ACOG: Hormone therapy for menopause url https://www.acog.org/womens-health/faqs/hormone-therapy-for-menopause label ACOG: Hormone testing during perimenopause url https://www.acog.org/womens-health/experts-and-stories/ask-acog/do-i-need-to-have-testing-of-my-hormone-levels-during-perimenopause"},{"url":"/patients/books/the-new-perimenopause","title":"The New Perimenopause","category":"Books","text":"The New Perimenopause Book Summary - Gennady Gelman The New Perimenopause Perimenopause · hormonal transition Mary Claire Haver focuses on the transition before menopause, including changes in menstrual cycles, mood, sleep, and sexual health. The book offers tools for preparing for appointments and discussing symptoms. This overview highlights its themes; the practical care points below are general patient education. Mary Claire Haver, MD The years before menopause can bring changes that disrupt daily life. The book emphasizes recognizing symptoms and asking for a thoughtful evaluation. Keep a record of your periods, symptoms, and their impact to bring to an appointment. Ask which treatment options address the symptoms that matter most to you. Do not assume every symptom is caused by perimenopause; other explanations may need evaluation. Hormone levels fluctuate during the transition, so routine hormone testing is often unnecessary. Does this pattern fit perimenopause, or should we look for another cause? Would hormonal or nonhormonal treatment be a reasonable option for me? label Publisher’s book overview url https://www.penguinrandomhouse.com/books/777456/the-new-perimenopause-by-mary-claire-haver-md/ label ACOG: Hormone therapy for menopause url https://www.acog.org/womens-health/faqs/hormone-therapy-for-menopause label ACOG: Hormone testing during perimenopause url https://www.acog.org/womens-health/experts-and-stories/ask-acog/do-i-need-to-have-testing-of-my-hormone-levels-during-perimenopause"},{"url":"/patients/books/the-obesity-code","title":"The Obesity Code","category":"Books","text":"The Obesity Code Book Summary - Gennady Gelman The Obesity Code Jason Fung, MD Metabolic health · fasting Jason Fung argues that body weight is regulated by hormones and food timing as well as calories. The book is most useful as a challenge to simplistic blame-and-willpower explanations of obesity. Obesity is a chronic, biologically regulated condition—not a character flaw. Insulin, food quality, sleep, stress, and meal timing can influence hunger and energy storage. Frequent restriction followed by regain is common because the body adapts to weight loss. Reduce highly refined carbohydrates and ultra-processed foods. Build meals around protein, fiber-rich plants, and minimally processed foods. If appropriate, discuss a consistent eating window rather than grazing throughout the day. The book treats insulin as a more complete explanation of obesity than current evidence supports. Fasting is not appropriate for everyone, including some people using diabetes medicines, pregnant patients, and those with eating-disorder histories. Calories still matter even when hormones affect appetite and expenditure. Would time-restricted eating be safe with my medicines and conditions? What is a realistic first weight or waist goal for me? Could sleep, stress, or a medication be affecting my weight?"},{"url":"/patients/books/why-we-get-sick","title":"Why We Get Sick","category":"Books","text":"Why We Get Sick Book Summary - Gennady Gelman Why We Get Sick Benjamin Bikman, PhD Insulin resistance · metabolic health Benjamin Bikman explains insulin resistance as a major contributor to metabolic disease and argues that improving insulin sensitivity can benefit weight, blood sugar, fatty liver, cardiovascular risk, and overall health. The framework is useful, but insulin resistance is one part of a complex, interconnected system—not the single cause of every chronic illness. Insulin resistance means that tissues respond less effectively to insulin, often prompting the pancreas to release more of it. It is closely associated with type 2 diabetes, fatty liver disease, cardiovascular risk, and many cases of obesity. Food quality, physical activity, sleep, stress, genetics, medicines, and body-fat distribution can all influence metabolic health. Build meals around minimally processed foods, adequate protein, fiber-rich plants, and portions that fit your needs. Combine regular aerobic activity with resistance training; even short walks after meals can help glucose regulation. Protect sleep and discuss blood pressure, waist circumference, glucose, triglycerides, and other metabolic markers with your clinician. The book sometimes presents insulin resistance as a more universal root cause than the total evidence supports. Obesity and insulin resistance can worsen each other; the relationship is not simply one-directional. Lower-carbohydrate eating can be useful for some people, but it is not the only effective approach and should not displace food quality, sustainability, or medication safety. Do I have clinical signs or laboratory evidence of insulin resistance or metabolic syndrome? Which nutrition pattern is most realistic and medically appropriate for me? Could my sleep, medicines, hormonal conditions, or other health problems be affecting my metabolic health?"},{"url":"/patients/books/why-we-sleep","title":"Why We Sleep","category":"Books","text":"Why We Sleep Book Summary - Gennady Gelman Why We Sleep Matthew Walker, PhD Sleep · performance Matthew Walker explains how sleep supports memory, emotional regulation, metabolism, immune function, and safety. The book succeeds at making sleep feel like essential health infrastructure rather than expendable downtime. Sleep is an active biological process that supports learning, repair, and regulation. Regular timing matters, not just total hours. Alcohol, late caffeine, light, temperature, pain, mood, and sleep disorders can all disrupt restorative sleep. Keep wake time consistent, including on most weekends. Create a wind-down period with lower light and less stimulation. Move caffeine earlier and notice whether alcohol fragments sleep. Some dramatic statistics and claims in the book have been disputed or overstated. Trying to perfect sleep can itself create anxiety and insomnia. Persistent snoring, witnessed pauses, restless legs, or daytime sleepiness need evaluation—not merely better sleep hygiene. Could I have sleep apnea or another sleep disorder? Would CBT-I be more useful than a sleeping medicine? Which part of my routine most undermines a consistent sleep window?"},{"url":"/patients","title":"Patient resources","category":"Patient resources","text":"Patient Resources - Gennady Gelman Plants Are Your Friends Plant-forward nutrition A conversational guide to eating more whole plant foods, inspired by the evidence-focused work of Dr. Michael Greger. https://plants-chat-663367173026.us-east1.run.app/ AI chatbot Open Plants Are Your Friends chatbot PLANT leaf Alex the Health Guide Everyday health coaching A supportive guide for realistic conversations about nutrition, exercise, sleep, habits, and sustainable lifestyle change. https://alex-663367173026.us-east1.run.app/ AI chatbot Open Alex the Health Guide chatbot ALEX sun GG Gennady Gelman, MD ← Main page Flu Weight Books Apps AI guides Search For patients & curious people Tools for healthier everyday choices. These conversational guides can help you explore practical changes, prepare questions, and learn at your own pace. Seasonal respiratory health Guide + interactive tools FLU Influenza Prevent it. Understand it. Know what helps. A practical guide to flu vaccination, symptoms, treatment, medication safety, warning signs, and building a custom comfort plan. Open the flu guide ↗ Weight & metabolic health 10 resources WEIGHT CONCERNS A practical starting point Understand your options. Choose your next step. Reliable reading on nutrition, calorie needs, physical activity, fasting, medications, surgery, and books I often discuss with patients. Explore weight resources ↗ Reading list 8 books OC HND HNDT WWS SATS Books I recommend to patients A small shelf for living better. Eight accessible books about metabolic health, food, sleep, menopause, and facing mortality—each with a short note about why it may be useful. Browse the shelf ↗ Practical tools iOS · Android + Apps I recommend to patients Put your phone to work for your health. Trusted tools for your health record, nutrition, sleep, medication reminders, development, symptoms, and focus—with direct platform links. Browse the apps ↗ Available now AI health guides 0 Open guide ↗ A useful boundary A guide—not your clinician. These tools provide general education, not diagnosis or personalized medical care. Do not include names, birth dates, medical-record numbers, or other identifying information. For urgent symptoms, contact a healthcare professional or emergency service directly. © Gennady Gelman me@gennadygelman.com"},{"url":"/patients/weight","title":"Weight concerns?","category":"Patient resources","text":"Weight Management Resources - Gennady Gelman 01 Start here Understanding obesity A plain-language overview of obesity, health risks, evaluation, and treatment options from the UMass Memorial Health Library. https://umassmemorial.staywellhealthlibrary.com/RelatedItems/85,P07855 Read the overview 02 Calorie needs NIH Body Weight Planner Estimate how changes in food intake and physical activity may affect weight over time. Treat the result as a planning estimate, not a prescription. https://www.niddk.nih.gov/bwp Open the planner 03 Food tracking MyFitnessPal Track food and calories when structured self-monitoring is useful. Tracking is not right for everyone, especially with a history of disordered eating. https://www.myfitnesspal.com/ Visit MyFitnessPal 04 Eating pattern Harvard Healthy Eating Plate A visual guide to building meals around vegetables, fruit, whole grains, healthy proteins, and healthier oils. https://www.hsph.harvard.edu/nutritionsource/healthy-eating-plate/ Review the plate 05 Meal timing 16/8 intermittent fasting An introduction to limiting eating to an eight-hour daily window. Fasting is optional—not inherently superior—and is not appropriate for everyone. https://www.healthline.com/nutrition/16-8-intermittent-fasting Read the guide 06 Movement Benefits of physical activity CDC guidance on how regular activity supports sleep, mood, mobility, heart health, diabetes prevention, and long-term independence. https://www.cdc.gov/physical-activity-basics/about/ Explore the benefits 07 Treatment options Medications for weight loss An overview of prescription treatment as one possible part of long-term obesity care. Medication choice should be individualized with a clinician. https://umassmemorial.staywellhealthlibrary.com/RelatedItems/85,P07858 Read about medications 08 Treatment options Metabolic and bariatric surgery An overview of surgical treatment for obesity, including who may benefit and why lifelong follow-up matters. https://umassmemorial.staywellhealthlibrary.com/RelatedItems/85,P07859 Read about surgery How Not to Diet Michael Greger, MD /patients/books/how-not-to-diet/ A patient-friendly summary of the book’s approach to food quality, habits, and sustainable weight management. The Obesity Code Jason Fung, MD /patients/books/the-obesity-code/ A patient-friendly summary of the book’s argument about insulin, eating patterns, and fasting—with important context about the evidence. Why We Get Sick Benjamin Bikman, PhD /patients/books/why-we-get-sick/ A patient-friendly summary of insulin resistance, metabolic health, and practical ways to improve both—with context about where the book overreaches. GG Gennady Gelman, MD ← Patient resources Search Weight & metabolic health There is more than one useful next step. Start with the resource that fits the question you have today. Lasting progress can include food, activity, sleep, support, medication, or surgery. ↗ Go deeper Three books to think with Patient summary by Read the summary → You do not have to do this alone Meet with a health coach. A referral can be made. Ask your care team whether health coaching is available and appropriate for you. For education—not individualized medical advice. Talk with your clinician before fasting, starting a weight-loss medication, or pursuing surgery—especially during pregnancy, with an eating-disorder history, or when using insulin or other glucose-lowering medication. © Gennady Gelman me@gennadygelman.com"},{"url":"/professional/books","title":"Recommended Books","category":"Books","text":"Recommended Medical Books - Gennady Gelman Recommended reading for patients, students, and colleagues, organized by topic. GG Gennady Gelman, MD ← Students & Colleagues Search Students & Colleagues Recommended Books Medicine, the human body, and the lives we lead. Tap a cover to learn more. Recommended reading invites discussion; it does not mean agreement with every claim. Use clinical guidance and individual circumstances when applying health advice. © Gennady Gelman me@gennadygelman.com Patient Provider Both id family title Pregnancy, Family & Women’s Health books title Far from the Tree author Andrew Solomon audience Both description An exploration of raising children whose identities differ profoundly from their parents’. cover /books/recommended/far-from-the-tree.jpg source https://www.simonandschuster.com/books/Far-From-the-Tree/Andrew-Solomon/9780743236720 title New Family Values author Andrew Solomon audience Both format Audio essay description An Audible Original exploring evolving definitions and arrangements of family. cover /books/recommended/new-family-values.jpg source https://www.audible.co.uk/pd/New-Family-Values-Audiobook/B07KCN9LVX title Dr. Susan Love’s Breast Book author Susan M. Love & Elizabeth Love audience Patient description A patient-oriented reference for breast health, screening, and breast cancer. cover /books/recommended/dr-susan-love-s-breast-book.jpg source https://www.hachette.co.uk/titles/elizabeth-love/dr-susan-loves-breast-book/9780306833250/ title The New Menopause author Mary Claire Haver audience Both description A guide to menopause symptoms, hormone therapy, and conversations about long-term health. cover /books/recommended/the-new-menopause.jpg source https://www.penguinrandomhouse.com/books/734501/the-new-menopause-by-mary-claire-haver-md/ title Expecting Better author Emily Oster audience Patient description An economist examines the evidence behind common pregnancy advice. cover /books/recommended/expecting-better.jpg source https://openlibrary.org/books/OL27541700M/Expecting_Better title Cribsheet author Emily Oster audience Patient description A data-driven guide to decisions during the first years of parenting. cover /books/recommended/cribsheet.jpg source https://www.penguinrandomhouse.com/books/572658/cribsheet-by-emily-oster/9780525559276/ title The Family Firm author Emily Oster audience Patient description A framework for making decisions about school-age children and family life. cover /books/recommended/the-family-firm.jpg source https://www.penguinrandomhouse.com/books/639450/the-family-firm-by-emily-oster/ title The Unexpected author Emily Oster & Nathan Fox audience Patient description A guide to navigating pregnancy complications and planning conversations about a future pregnancy. cover /books/recommended/the-unexpected.jpg source https://www.penguinrandomhouse.com/books/717163/the-unexpected-by-emily-oster-and-nathan-fox-md/ id body title Body, Genetics & Evolution books title The Body: A Guide for Occupants author Bill Bryson audience Patient description An accessible tour of the human body and the discoveries that shape our understanding of it. cover /books/recommended/the-body-a-guide-for-occupants.jpg source https://www.penguinrandomhouse.com/books/239783/the-body-by-bill-bryson/ title Gulp author Mary Roach audience Both description A curious, often funny journey through the alimentary canal. cover /books/recommended/gulp.jpg source https://microcosmpublishing.com/catalog/books/6800 title The Wild Life of Our Bodies author Rob Dunn audience Both description An exploration of the relationships between human evolution, other species, and modern health. cover /books/recommended/the-wild-life-of-our-bodies.jpg source https://www.vitalsource.com/products/the-wild-life-of-our-bodies-dr-rob-dunn-v9780062092274 title Sapiens author Yuval Noah Harari audience Both description A broad history of humankind, from the cognitive revolution to the modern world. cover /books/recommended/sapiens.jpg source https://www.penguin.co.uk/books/419795/sapiens-by-harari-yuval-noah/9781529913934 title The Gene: An Intimate History author Siddhartha Mukherjee audience Both description A history of genetics, its discoveries, and its consequences for individuals and society. cover /books/recommended/the-gene-an-intimate-history.jpg source https://openlibrary.org/books/OL26359464M/The_Gene title A Crack in Creation author Jennifer Doudna & Samuel H. Sternberg audience Both description An account of CRISPR gene editing and the ethical questions it raises. cover /books/recommended/a-crack-in-creation.jpg source https://openlibrary.org/books/OL26362974M/A_Crack_in_Creation id cancer title Cancer & Medical Ethics books title The Emperor of All Maladies author Siddhartha Mukherjee audience Both description A biography of cancer through the stories of patients, physicians, and researchers. cover /books/recommended/the-emperor-of-all-maladies.jpg source https://openlibrary.org/books/OL30778101M/The_Emperor_of_All_Maladies title The Immortal Life of Henrietta Lacks author Rebecca Skloot audience Both description The story of Henrietta Lacks and HeLa cells, alongside questions of race, consent, and research ethics. cover /books/recommended/the-immortal-life-of-henrietta-lacks.jpg source https://www.randomhousebooks.com/books/168191/C1/ id nutrition title Nutrition, Obesity & Longevity books title How Not to Die author Michael Greger audience Patient description A case for plant-based eating and its role in disease prevention. cover /books/recommended/how-not-to-die.jpg source https://us.macmillan.com/books/9781250066114/hownottodie/ title How Not to Age author Michael Greger audience Patient description An examination of nutrition and lifestyle approaches to aging. cover /books/recommended/how-not-to-age.jpg source https://openlibrary.org/books/OL36665703M/How_Not_to_Age title The Obesity Code author Jason Fung audience Patient description An insulin-focused account of obesity, with an emphasis on eating patterns and fasting. cover /books/recommended/the-obesity-code.jpg source https://covers.openlibrary.org/b/isbn/9781771641258-L.jpg title Outlive author Peter Attia with Bill Gifford audience Both description A proactive approach to prevention, healthspan, and the goals of long-term health. cover /books/recommended/outlive.jpg source https://www.penguinrandomhouse.com/books/705161/outlive-by-peter-attia-md-with-bill-gifford/ title Good to Go author Christie Aschwanden audience Both description A critical look at the science and business of exercise recovery. cover /books/recommended/good-to-go.jpg source https://books.google.com/books/about/Good_to_Go.html?id=HVSNEAAAQBAJ title The Hacking of the American Mind author Robert Lustig audience Both description An argument about reward, pleasure, and how food and technology shape behavior. cover /books/recommended/the-hacking-of-the-american-mind.jpg source https://books.google.com/books/about/The_Hacking_of_the_American_Mind.html?id=K1hqDwAAQBAJ id mind title Mind, Mental Health & Consciousness books title The Body Keeps the Score author Bessel van der Kolk audience Both description A clinical perspective on trauma, its effects, and approaches to recovery. cover /books/recommended/the-body-keeps-the-score.jpg source https://www.penguinrandomhouse.com/books/313183/the-body-keeps-the-score-by-bessel-van-der-kolk-md/ title How to Change Your Mind author Michael Pollan audience Both description A journey through psychedelics, their history, and the renewed interest in mental-health research. cover /books/recommended/how-to-change-your-mind.jpg source https://www.penguinrandomhouse.com/books/529343/how-to-change-your-mind-by-michael-pollan/ title The Noonday Demon author Andrew Solomon audience Both description A personal and clinical exploration of depression and the lives it touches. cover /books/recommended/the-noonday-demon.jpg source https://openlibrary.org/books/OL28225852M/The_Noonday_Demon title Staring at the Sun author Irvin Yalom audience Both description A therapist’s reflections on death anxiety and living more fully. cover /books/recommended/staring-at-the-sun.jpg source https://covers.openlibrary.org/b/isbn/9780787996680-L.jpg title My Stroke of Insight author Jill Bolte Taylor audience Both description A neuroanatomist’s first-person account of stroke and recovery. cover /books/recommended/my-stroke-of-insight.jpg source https://www.penguinrandomhouse.com/books/304515/my-stroke-of-insight-by-jill-bolte-taylor/9780452295544/ title Consciousness Explained author Daniel Dennett audience Both description A philosophical account of consciousness and how the mind works. cover /books/recommended/consciousness-explained.jpg source https://www.hachettebookgroup.com/titles/danile-c-dennett/consciousness-explained/9780316180665/ title The Moral Landscape author Sam Harris audience Both description An argument that scientific understanding of well-being can inform ethics. cover /books/recommended/the-moral-landscape.jpg source https://www.simonandschuster.com/books/The-Moral-Landscape/Sam-Harris/9781439171226 id mortality title Death, Dying & End-of-Life Care books title Being Mortal author Atul Gawande audience Both description Reflections on aging, end-of-life care, autonomy, and what makes life worth living. cover /books/recommended/being-mortal.jpg source https://us.macmillan.com/books/9780805095159/beingmortal/ title How We Die author Sherwin Nuland audience Both description A physician’s account of the biology of dying and the human experience surrounding it. cover /books/recommended/how-we-die.jpg source https://www.penguinrandomhouse.com/books/122995/how-we-die-by-sherwin-b-nuland/ title On Death and Dying author Elisabeth Kübler-Ross audience Both description Conversations about the experience of dying that introduced the five-stages framework. cover /books/recommended/on-death-and-dying.jpg source https://openlibrary.org/books/OL22149363M/On_death_and_dying title The Five Invitations author Frank Ostaseski audience Both description A hospice teacher reflects on what an awareness of death can teach us about living. cover /books/recommended/the-five-invitations.jpg source https://academic.macmillan.com/academictrade/9781250076748/thefiveinvitations/ id systems title Healthcare System, Diagnosis & Public Health books title An American Sickness author Elisabeth Rosenthal audience Both description An investigation of the business of American healthcare and its effects on patients. cover /books/recommended/an-american-sickness.jpg source https://www.penguinrandomhouse.com/books/318776/an-american-sickness-by-elisabeth-rosenthal/ title Blind Spots author Marty Makary audience Both description A critique of medical assumptions and groupthink, with cases for reexamining accepted ideas. cover /books/recommended/blind-spots.jpg source https://www.bloomsbury.com/us/blind-spots-9781639735310/ title The Age of Diagnosis author Suzanne O’Sullivan audience Both description A neurologist examines diagnostic labels and the potential harms of overdiagnosis. cover /books/recommended/the-age-of-diagnosis.jpg source https://www.penguinrandomhouse.com/books/767687/the-age-of-diagnosis-by-dr-suzanne-osullivan/ title Everything Is Tuberculosis author John Green audience Both description Tuberculosis as a window into history, inequity, and the human consequences of disease. cover /books/recommended/everything-is-tuberculosis.jpg source https://www.penguinrandomhouse.com/books/312472/everything-is-tuberculosis-by-john-green/ title Random Acts of Medicine author Anupam B. Jena & Christopher Worsham audience Both description Natural experiments that reveal unexpected influences on healthcare and outcomes. cover /books/recommended/random-acts-of-medicine.jpg source https://books.google.com/books/about/Random_Acts_of_Medicine.html?id=QFjzEAAAQBAJ id practice title Medical Practice, Career & Reflections books title The Checklist Manifesto author Atul Gawande audience Provider description How checklists can help people manage complexity and improve performance in medicine. cover /books/recommended/the-checklist-manifesto.jpg source https://academic.macmillan.com/academictrade/9780805091748/thechecklistmanifesto/ title Deep Medicine author Eric Topol audience Provider description A vision for how artificial intelligence could change clinical practice and the patient–physician relationship. cover /books/recommended/deep-medicine.jpg source https://openlibrary.org/books/OL27754269M/Deep_Medicine title A Giant Leap author Robert Wachter audience Provider description An examination of generative AI in medicine and the move from early experiments to clinical practice. cover /books/recommended/a-giant-leap.jpg source https://www.penguinrandomhouse.com/books/776443/a-giant-leap-by-robert-wachter-md/ title Health Design Thinking author Bon Ku & Ellen Lupton audience Provider description An introduction to applying design methods to problems in healthcare. cover /books/recommended/health-design-thinking.jpg source https://mitpress.mit.edu/9780262543606/health-design-thinking/ title The Invention of Surgery author David Schneider audience Provider description A history of surgery, its innovators, and the development of modern surgical technology. cover /books/recommended/the-invention-of-surgery.jpg source https://inkwellmanagement.com/books/the-invention-of-surgery title Memorizing Pharmacology author Tony Guerra audience Provider description A study guide using memory techniques to organize pharmacology knowledge. cover /books/recommended/memorizing-pharmacology.jpg source https://www.lulu.com/shop/tony-guerra/memorizing-pharmacology-a-relaxed-approach/paperback/product-19kjvmkz.html"},{"url":"/professional","title":"Professional resources","category":"Professional resources","text":"Professional Resources - Gennady Gelman AI & large language models General-purpose assistants, clinical AI tools, ambient documentation, and journals following AI in medicine. ChatGPT General-purpose AI assistant for questions, drafting, analysis, and summarization. https://chatgpt.com/ Web · iOS · Android Claude Anthropic assistant with strong long-context reading and writing capabilities. https://claude.ai/ Web · iOS · Android Google Gemini Google's assistant, integrated with Search and Workspace. https://gemini.google.com/ Web · iOS · Android Microsoft Copilot Microsoft assistant integrated across Bing, Edge, Windows, and Microsoft 365. https://copilot.microsoft.com/ Web · iOS · Android Perplexity AI answer engine with web search and inline source links. https://www.perplexity.ai/ Web · iOS · Android NotebookLM Research assistant for organizing and asking questions across source documents. https://notebooklm.google.com/ Web OpenEvidence Clinician-focused medical evidence search and summarization. https://www.openevidence.com/ Web · iOS · Android Doximity GPT Clinician chatbot with drug reference and clinical-document drafting tools. https://www.doximity.com/ Web · iOS · Android Linus Health AI-augmented digital cognitive assessment platform. https://linushealth.com/ iPad Brook Health Remote patient monitoring and health coaching for chronic conditions. https://www.brook.health/ Web · iOS · Android NEJM AI Peer-reviewed research and commentary on AI in medicine. https://ai.nejm.org/ Web JAMA AI collection JAMA Network research and commentary about AI in healthcare. https://jamanetwork.com/collections/44020/artificial-intelligence Web Clinical calculators & decision support High-yield tools for risk estimation, prevention, prescribing, and shared decision-making. MDCalc Medical calculators, equations, and clinical decision-support tools. https://www.mdcalc.com/ Web · iOS · Android USPSTF ePSS Preventive-care recommendations searchable by age, sex, and risk factors. https://epss.ahrq.gov/ePSS/search.jsp Web · iOS · Android AHA PREVENT Calculator Estimates 10- and 30-year total cardiovascular disease risk. https://professional.heart.org/en/guidelines-and-statements/prevent-calculator Web QRISK3 Open 10-year cardiovascular-risk calculator incorporating additional comorbidities. https://qrisk.org/ Web FRAX Ten-year fracture-risk estimate with or without bone mineral density. https://frax.shef.ac.uk/FRAX/ Web TheNNT Treatment reviews organized around benefit, harm, NNT, and NNH. https://thennt.com/ Web SEER Cancer Stat Facts NCI cancer incidence, mortality, and survival statistics. https://seer.cancer.gov/statfacts/ Web Guidelines & core references Frequently used primary-care journals, guidelines, and point-of-care references. American Family Physician AAFP's peer-reviewed clinical journal for family physicians. https://www.aafp.org/pubs/afp.html FamilyDoctor.org AAFP patient-facing health information. https://familydoctor.org/ Family Practice Notebook Concise, actively maintained primary-care reference. https://fpnotebook.com/ Radiopaedia Peer-reviewed radiology reference and teaching-case library. https://radiopaedia.org/ ADA Standards of Care Current diabetes standards, tables, and clinical recommendations. https://professional.diabetes.org/standards-of-care GOLD COPD Report Global strategy for COPD diagnosis, management, and prevention. https://goldcopd.org/ GINA Asthma Strategy Global evidence-based asthma management and prevention strategy. https://ginasthma.org/ KDIGO CKD Guideline Guidance for CKD evaluation and management. https://kdigo.org/guidelines/ckd-evaluation-and-management/ Pharmacy, vaccines & travel Medication access, lactation safety, opioid guidance, immunization, and travel health. GoodRx Local cash-price comparison and prescription coupons. https://www.goodrx.com/ LactMed NIH database on medications, lactation, and breastfed infants. https://www.ncbi.nlm.nih.gov/books/NBK501922/ CDC Opioid Prescribing Guideline Clinical practice guidance for prescribing opioids for pain. https://www.cdc.gov/overdose-prevention/hcp/clinical-guidance/ CDC Travelers' Health Destination-specific health and vaccine recommendations. https://wwwnc.cdc.gov/travel/ CDC Vaccine Schedules Current child, adolescent, adult, and catch-up schedules. https://www.cdc.gov/vaccines/hcp/imz-schedules/ PneumoRecs VaxAdvisor Patient-specific CDC pneumococcal vaccine guidance. https://www.cdc.gov/pneumococcal/hcp/vaccine-recommendations/app/index.html Mental health & substance use Validated screeners and practical clinical tools. Insomnia Coach Free VA CBT-I-based self-care app with a guided training plan, sleep diary, and tools for managing insomnia. https://mobile.va.gov/app/insomnia-coach PHQ Screeners PHQ-9, GAD-7, PHQ-15, and related validated instruments. https://www.phqscreeners.com/ WHO AUDIT Alcohol Use Disorders Identification Test and implementation guidance. https://www.who.int/publications/i/item/WHO-MSD-MSB-01.6a Pediatrics & family health Parent education, preventive-care schedules, milestones, and community prevention. KidsHealth Nemours-backed information for parents, children, and teens. https://kidshealth.org/ HealthyChildren.org AAP-backed parent guidance across ages, stages, safety, and nutrition. https://www.healthychildren.org/ Bright Futures AAP periodicity schedule, anticipatory guidance, and visit resources. https://www.aap.org/en/practice-management/bright-futures/ CDC Milestone Tracker Developmental milestones from 2 months through age 5. https://www.cdc.gov/ncbddd/actearly/milestones-app.html Massachusetts fluoridation status Community water-system fluoridation information. https://www.mass.gov/info-details/community-water-fluoridation Women's & reproductive health Contraception, pregnancy, reproductive care, and cervical-screening guidance. Bedsider Patient-centered birth-control information and access support. https://www.bedsider.org/ ACOG Clinical Practice bulletins, committee opinions, calculators, and clinical tools. https://www.acog.org/clinical Reproductive Health Access Project Free multilingual patient fact sheets and clinician guides. https://www.reproductiveaccess.org/ ASCCP Guidelines Risk-based management for abnormal cervical-cancer screening results. https://www.asccp.org/guidelines/ Geriatrics & community resources Medication review, deprescribing, symptom support, and social-care navigation. AGS Beers Criteria Potentially inappropriate medications in adults 65 and older. https://www.americangeriatrics.org/media-center/news/older-people-medications-ags-beers-criteria Deprescribing.org Evidence-based deprescribing algorithms and patient handouts. https://deprescribing.org/ Ada Patient-facing symptom assessment tool. https://ada.com/ Findhelp Search for free and reduced-cost food, housing, transport, and financial support. https://www.findhelp.org/ Clinical Problems Caused by Obesity https://www.ncbi.nlm.nih.gov/books/NBK278973/ Effects of Intermittent Fasting on Health, Aging, and Disease https://www.nejm.org/doi/full/10.1056/NEJMra1905136 Serial Bone-Density Measurement for Osteoporosis Screening https://www.nejm.org/doi/full/10.1056/NEJMoa1107142 SELECT: Semaglutide and Cardiovascular Outcomes in Obesity https://www.nejm.org/doi/full/10.1056/NEJMoa2307563 SURMOUNT-1: Tirzepatide Once Weekly for Obesity https://www.nejm.org/doi/full/10.1056/NEJMoa2206038 FLOW: Semaglutide in CKD with Type 2 Diabetes https://www.nejm.org/doi/full/10.1056/NEJMoa2403347 BUN/creatinine >20:1 may support upper GI bleeding or a prerenal pattern; interpret in clinical context. Mentzer index MCV ÷ RBC count: <13 supports thalassemia trait; >13 supports iron deficiency. Albumin:globulin ratio Albumin ÷ (total protein − albumin); an inverted ratio or large globulin gap warrants context and possible monoclonal-protein testing. Corrected sodium Measured Na + 1.6 × (glucose − 100)/100; consider 2.4 at very high glucose. Corrected calcium Measured Ca + 0.8 × (4 − albumin); use ionized calcium when accuracy matters. Albumin-corrected anion gap AG + 2.5 for each 1 g/dL albumin below 4. FENa / FEUrea FENa <1% or FEUrea <35% can support a prerenal pattern; diuretics and CKD limit interpretation. GG Gennady Gelman, MD ← Main page Search For students & colleagues A working library for primary care. Resources I share during rotations and with fellow clinicians—selected for practical usefulness, not completeness. Clinical Tools & Resources Recommended Books Lab pearls Articles Epic basics UMass resources Search & explore Clinical Tools & Resources Browse clinical AI, calculators, guidelines, apps, articles, and lab pearls. Filter by topic or resource type. Open directory → The bookshelf Recommended Books Reading for patients and providers, from genetics and mental health to medical practice and the healthcare system. Browse the books → Reference shelf Clinical resources 0 + Open ↗ Quick reference Lab pearls Useful first-pass calculations—signals, not diagnoses. Verify formulas and interpret them in the full clinical context. Often referenced Articles worth knowing 0 Read ↗ Rotation essentials Epic basics Pre-chart; do not start the visit Prepare agenda items, likely orders, prior history, and care gaps in advance. Never start the encounter before the patient arrives. Keep the problem list meaningful Merge duplicates, resolve inactive problems, reject noise, and distinguish longitudinal problems from diagnoses addressed today. Use search before hunting Alt + Space opens Epic search. Use it for activities, orders, calculators, and trends. Let suggestions populate before pressing Enter. Build your documentation toolkit Use Smart Butler (.?) to find SmartPhrases, SmartText, and SmartLinks. Copy useful phrases, then revise them into your own voice. Document HCCs honestly MEAT what you address: Monitor, Evaluate, Assess/Address, or Treat. A diagnosis on a list is not adequate support by itself. Order with collection in mind Confirm clinic-collect versus lab-collect settings, future dates, available point-of-care tests, and local vaccine workflows. Local configuration changes. Use current organizational job aids and ask the clinical team when a workflow is uncertain. UMass-specific Programs to know 01 Digital Health & RPM Connected monitoring and coaching through the Digital Health workflow, including hypertension, diabetes, heart failure, and weight management. Brook Health ↗ 02 Advanced Therapeutics / 340B Medication-access pathways may help eligible patients obtain high-cost therapies. Eligibility and payer rules vary. HRSA overview ↗ 03 Complex Care & legal support Care management may address transport, food, housing, utilities, benefits, and health-related civil legal needs. Findhelp ↗ 04 CommunityHelp Massachusetts resource navigation by ZIP code and need, with clinician referral capabilities. CommunityHelp ↗ This page is an informal learning aid, not an official UMass Memorial policy or workflow document. Verify current eligibility and referral steps in Epic or with the responsible team. Use your clinical judgment. External tools, calculators, AI systems, and summaries can be incomplete or wrong. Do not enter identifiable patient information into a tool unless its approved privacy and security status is clear. © Gennady Gelman me@gennadygelman.com"},{"url":"/tools/antidepressant","title":"Older adult","category":"Clinical tools","text":"use client familyBenefit familyMedication patientTrial higherAcuity pain duloxetineTrial anxiety activation sideEffects interactions age history specialty duloxetine anxiousSsri venlafaxine bupropion escitalopram teen adult older Escitalopram Sertraline Fluoxetine Citalopram Paroxetine Bupropion Venlafaxine Desvenlafaxine Duloxetine Mirtazapine Vortioxetine Vilazodone Trazodone A tricyclic antidepressant Another antidepressant Treatment history Was there a clear past benefit? Consider the patient and first-degree relatives. A convincing prior response can be more useful than small average differences between medications. Treatment history Which medication helped? Choose the antidepressant associated with the clearest benefit for the patient or family member. Treatment history Has this patient tried it? A family response is useful only if the patient has not already had an adequate unsuccessful or intolerable trial. Safety gate Is there a reason not to use this pathway? Screen for bipolar-spectrum illness or mania, psychosis, catatonia, postpartum psychosis, or an acute suicide risk requiring a higher level of care. Co-target Is chronic pain a major treatment target? Examples include diabetic neuropathic pain, fibromyalgia, or chronic musculoskeletal pain where one medication might reasonably address both conditions. Pain pathway Has the patient already tried duloxetine? If duloxetine already failed despite an adequate trial, return to the main pathway instead of recommending it again. Symptom profile Is prominent anxiety part of the presentation? Think generalized anxiety, panic symptoms, marked rumination, or an anxious distress presentation that should influence the first choice. Tolerability Would activation or withdrawal sensitivity be a concern? Favor a calmer, easier-to-manage SSRI when jitteriness, insomnia, blood-pressure effects, or discontinuation symptoms are especially concerning. Tolerability Are sexual side effects, fatigue, or weight gain a leading concern? Bupropion can be attractive when these tradeoffs matter, if its contraindications and activating profile are acceptable. Medication fit Is a relatively simple interaction profile especially important? Medication reconciliation still matters, but escitalopram is often a pragmatic option when minimizing interaction complexity is a priority. Age context Which age group best fits the patient? Age affects the evidence base, dosing caution, adverse-effect monitoring, and which options are easiest to defend as a first choice. VA/DoD major depression guideline https://www.healthquality.va.gov/guidelines/mh/mdd/ NICE depression recommendations https://www.nice.org.uk/guidance/ng222/chapter/recommendations VA/DoD bipolar disorder guideline https://www.healthquality.va.gov/guidelines/mh/bd/ ACOG perinatal mental-health guidance https://www.acog.org/clinical/clinical-guidance/clinical-practice-guideline/articles/2023/06/treatment-and-management-of-mental-health-conditions-during-pregnancy-and-postpartum FDA antidepressant suicidality advisory https://www.fda.gov/media/132665/download DailyMed prescribing information https://dailymed.nlm.nih.gov/dailymed/ familyBenefit familyBenefit GG Gennady Gelman, MD ← Clinical tools Search Clinician decision support · v1.2 Antidepressant Chooser A structured way to turn response history, prior trials, safety, co-targets, tolerability, interactions, and age into a defensible starting option. Clinical-opinion disclaimer These recommendations reflect my clinical opinions. They are not a guideline, diagnosis, or substitute for shared decision-making, current prescribing information, medication reconciliation, or independent clinician judgment. Best-fit direction from this pathway Why it surfaced Before prescribing This is a decision-support result, not an instruction to prescribe. Confirm diagnosis, prior dose/duration/adherence, contraindications, interactions, pregnancy status when relevant, and current FDA labeling. ← Back Start over Pathway logic familyBenefit familyBenefit active Prior or family benefit higherAcuity higherAcuity active Safety screen pain pain duloxetineTrial active Pain co-target anxiety anxiety activation active Anxiety and activation sideEffects sideEffects active Side-effect priorities interactions interactions age active Interactions and age A failed patient trial deliberately falls back into the tree. The same is true when duloxetine has already failed in the pain branch. References Sources that support the pathway These sources support safety screening, broad medication-selection principles, monitoring, and labeled indications. The exact branching and weighting are my synthesis and opinion. ↗ Important Use the result as a conversation starter. Reassess suicidality, bipolar features, substance use, medical contributors, concurrent medications, adherence, and patient preference. For urgent safety concerns or diagnostic uncertainty, use the appropriate emergency or specialty pathway. © Gennady Gelman me@gennadygelman.com familyBenefit familyMedication Yes higherAcuity No or uncertain familyMedication Medication with prior benefit Select a medication… patientTrial Continue patientTrial history Never tried this medication history Tried and helped higherAcuity Tried and failed higherAcuity specialty Yes or uncertain pain No pain duloxetineTrial Yes anxiety No duloxetineTrial duloxetine Never tried duloxetine Tried and helped anxiety Tried and failed anxiety activation Yes sideEffects No activation anxiousSsri Yes venlafaxine No sideEffects bupropion Yes interactions No interactions escitalopram Yes age No age teen Adolescent adult Adult older Older adult → The medication with prior benefit the previously beneficial medication A clear personal response—or a first-degree family response when the patient has not already failed the drug—can offer useful individualized evidence. Verify who benefited, diagnosis, dose, duration, adherence, magnitude of benefit, adverse effects, reason for stopping, and present-day interactions or contraindications. Pause routine antidepressant selection Use urgent, emergency, or specialty assessment before choosing antidepressant monotherapy. Possible bipolarity, psychosis, catatonia, postpartum psychosis, or acute suicide risk changes the risk-benefit calculation and may require a different treatment setting. Clarify immediate safety, manic or mixed symptoms, psychosis, substance effects, pregnancy/postpartum context, supports, and level-of-care needs. Duloxetine A reasonable first option when depression and a relevant chronic pain syndrome are both meaningful treatment targets. Duloxetine has antidepressant efficacy and labeled pain indications, allowing one medication to address two clinically important domains. Review prior exposure, blood pressure, liver and renal considerations, alcohol use, interactions, nausea, activation, and discontinuation planning. Sertraline or escitalopram Favor a flexible SSRI start when prominent anxiety is paired with concern about activation or difficult discontinuation. These are pragmatic first-line choices with broad clinical familiarity and room for gradual titration according to sensitivity and response. Review prior trials, GI effects, sexual adverse effects, sodium and bleeding risks when relevant, QT considerations, interactions, and early activation. Venlafaxine XR Consider an SNRI when prominent anxiety is present and activation, blood-pressure monitoring, and discontinuation planning are acceptable. Venlafaxine can address depression and anxiety, with a clinically useful dose range when an SNRI strategy fits the patient. Review blood pressure, prior withdrawal sensitivity, overdose risk, interactions, activation, adherence reliability, and a future taper plan. Bupropion XL Consider bupropion when fatigue, sexual adverse effects, or weight gain are leading concerns and activation is acceptable. Its adverse-effect profile differs from serotonergic antidepressants and can fit patients prioritizing energy and sexual tolerability. Exclude seizure disorder and eating disorders; review anxiety, insomnia, blood pressure, alcohol or sedative withdrawal, interactions, and formulation-specific dosing. Escitalopram A pragmatic SSRI option when a relatively straightforward interaction profile and simple titration are priorities. It is commonly used as a first-line antidepressant and is often easier to fit into a complex medication list than stronger enzyme inhibitors. Review QT risk, sodium, bleeding risk, serotonergic combinations, sexual adverse effects, age-related dosing, and prior SSRI exposure. Fluoxetine A defensible evidence-based first direction for adolescent major depression, paired with close monitoring and psychotherapy when appropriate. Fluoxetine has a substantial youth evidence base and FDA approval for major depressive disorder in pediatric patients aged 8 years and older. Confirm diagnosis and age, screen for bipolarity, discuss the boxed warning, establish family-supported monitoring, assess interactions, and plan early follow-up. Sertraline or escitalopram A conventional first-line SSRI direction when no stronger historical, safety, pain, anxiety, tolerability, or interaction signal dominates. Both are broadly used first-line options; the tie-breaker should be patient preference, prior exposure, adverse-effect concerns, comorbidity, cost, and interactions. Verify bipolar screen, suicidality, medication list, pregnancy considerations, sodium and bleeding risks, sexual effects, and the planned follow-up interval. Sertraline or low-dose escitalopram Favor a conservative SSRI start with slow titration and deliberate monitoring in an older adult. These are familiar options when minimizing anticholinergic burden and interaction complexity matters, but age-related vulnerability still requires caution. Review falls, sodium, QT risk, bleeding risk, renal and hepatic function, polypharmacy, cognition, adherence, and dose limits in current labeling."},{"url":"/tools","title":"Clinical tools","category":"Clinical tools","text":"Clinical Calculators and Tools - Gennady Gelman /tools/lab-analyzer/ Clinical interpretation Clinical Lab Pattern Analyzer v1.8 Turn pasted laboratory results into calculated relationships, pattern-level interpretations, and concise next-step considerations. Derived calculations Color-coded cards Sources and next steps amber /tools/cv-risk/ Cardiovascular prevention CV Risk Decision Tool v20 Parse an Epic SmartPhrase, review PREVENT-based risk, lipid targets, risk enhancers, and treatment considerations in one clinician-focused workflow. Epic paste-and-parse Risk stratification Therapy guidance coral /tools/immunizations/ Pediatric prevention Pediatric Vaccine Guidance v0.3 Paste a child’s Epic immunization history and DOB to review routine vaccine status, timing, and parent-facing next steps. Epic immunization parsing Routine schedule review Parent-ready plan teal /tools/raf-calculator/ Medicare Advantage 2026 RAF Calculator V28 Paste demographics and an Epic-style problem list, review conservative diagnosis-to-ICD matches, and calculate the raw CMS-HCC V28 risk score. Problem-list parsing Auditable ICD review Official CMS logic green /tools/diabetes-type/ Diabetes classification Diabetes Type Evidence Tool v1.0 Combine islet autoantibodies, C-peptide context, and family history to identify the diabetes phenotype best supported by the available evidence. Autoantibody pattern C-peptide context Transparent rationale blue /tools/antidepressant/ Mental health Antidepressant Chooser v1.1 Move through prior response, medication trial history, safety, co-targets, tolerability, interactions, and age to identify a sensible antidepressant option. Interactive pathway Prior-trial fall-through Source-supported rationale violet GG Gennady Gelman, MD ← Main page Search Clinician-built decision support Clinical tools Small, practical tools designed to turn pasted EHR data into structured, reviewable decision support. Calculations run in your browser. Pasted patient data is not transmitted or stored by these tools. http _blank http noreferrer 0 Open tool ↗ Important Clinician use only. These tools provide clinical decision support and are not diagnostic devices. Verify parsed values and calculations, consult current source guidance, and apply independent clinical judgment. © Gennady Gelman me@gennadygelman.com"},{"url":"/kiloday","title":"Kiloday Celebration Calculator - Gennady Gelman","category":"Explore","text":"Kiloday Celebration Calculator - Gennady Gelman ← GennadyGelman.com The Kiloday Gazette Base-10 Living 1K A rational alternative to birthdays The kiloday is the new birthday. We count in base 10. We measure in base 10. We celebrate in… solar orbits? It's time to fix that. 1,000 days 2,000 days 5,000 days 10,000 days 25,000 days § 1 — Origins Birthdays are pagan rituals. Here's the receipts. 01 Candle fire magic Ancient Greeks lit candles on moon-cakes offered to Artemis — the smoke carried petitions skyward. We do this every year. Completely unironically. 02 Communal chanting \\"Happy Birthday\\" is mass unison chanting around a fire-lit object. This ritual structure predates writing. The song itself is from 1893. The bones are much older. 03 Wishing on the flame Making a silent wish before extinguishing fire is direct pyromancy — divination and petition via flame — from Mesopotamian and Greek mystery cults. 04 The protective circle Gathering in a ring around the honored person, facing inward with a lit centerpiece, mirrors Germanic and Celtic protective circle magic to ward off spirits. 05 Solar-cycle worship The birthday marks one revolution around the sun. Astronomers literally call it a \\"solar return.\\" This is astrological observation dressed in frosting. 06 Evil-eye vulnerability Many traditions held the birthday person was exposed to malicious spirits. Party horns, bright colors, and noise were apotropaic magic — demon deterrents. 07 Tributary gift-giving Bringing offerings to the honored person mirrors votive offerings to gods and emperors. Roman dies natalis rites were performed for gods before people. 08 The birthday crown Crowns and tiaras derive from Greek laurel wreaths and Roman imperial birthday rites — marking the wearer as temporarily divine, set apart, protected. § 2 — The Argument We live in base 10. Celebrate like it. Every milestone that matters is a power of ten. $100k salary. 1M followers. 10-year anniversary. A century. Billion-dollar valuation. Our entire numerical civilization runs on base 10 — currency, measurement, computation, science. Yet for the most personal milestones of all — the years of our lives — we still use solar orbits. An arbitrary, non-decimal, astronomical unit that wobbles with leap years and has nothing to do with how humans actually count. Kilodays fix this. 1,000 days is 1,000 days. Absolute. Precise. Universal. And it arrives ~3× more often than a birthday, giving you more occasions to reflect and celebrate. 1 kiloday Age ~2.7 — first real milestone 5 kilodays Age ~13.7 — young adulthood 10 kilodays Age ~27.4 — five figures of days 20 kilodays Age ~54.8 — deep wisdom territory 30 kilodays Age ~82.1 — rare and venerable 1,000 days — each cell = 10 days How many days have you been alive? Enter your birth date. Find your kiloday. Date of birth Calculate → — Days alive — Kilodays — Calendar years — Days to next kiloday Upcoming kilodays § 3 — The Ritual Food Celebrate with pound cake. Pound cake is the only rational kiloday cake. It was invented with its own base-10 logic: one pound each of flour, butter, eggs, and sugar. Four equal parts. Pure arithmetic. The original recipe is a mathematical statement. Write your kiloday number in icing. No candles required. 01 Preheat oven to 325°F (163°C). Grease and flour a standard loaf or bundt pan. 02 Cream butter and sugar together until pale and fluffy — approximately 5 minutes with a stand mixer. 03 Add eggs one at a time, beating well after each addition. Scrape the bowl. 04 Gently fold in flour, salt, and baking powder. Do not overmix — stop when just combined. 05 Add vanilla extract and fold once more. 06 Pour into prepared pan. Bake 60–75 minutes until a skewer comes out clean. 07 Cool 15 minutes in pan, then turn out onto a rack. Ice with your kiloday number. The base recipe Unsalted butter, softened 1 lb / 454 g Granulated sugar 1 lb / 454 g Large eggs (~8) 1 lb / 454 g All-purpose flour 1 lb / 454 g Vanilla extract 1 tsp Fine salt ½ tsp Baking powder 1 tsp The original 18th-century recipe had no leavening — just the four equal pounds. Modern baking powder is optional but recommended. The Kiloday Project Happy kiloday. Base 10 · Always"},{"url":"/medicolalia/no-1","title":"Medicolalia No. 1 - Gennady Gelman","category":"Explore","text":"Medicolalia No. 1 - Gennady Gelman Medicolalia · Radically examining medical terminology · No. 1 Migraines: The Headache Is Only Half the Story By Gennady Gelman, MD Migraine is a word that is half right. It means “half a head.” Many attacks involve both halves. Some involve no head pain at all. And the disorders that now officially carry the Greek name for “half a head” are not migraine. To see how that happened, start with the word and follow it. Take the word apart Migraine descends, by a winding route through Latin and French , from Greek hēmikrania : hēmi- , half, and kranion , skull or head. You likely already know hemi- from hemisphere (half a sphere), hemiplegia (paralysis of one side), and hemithorax (one side of the chest). Cranium is the bony case around the brain. The board game Cranium promises to exercise what is inside the box; strictly speaking, it is named for the box. The word appears in Galen’s surviving second-century writings. Aretaeus of Cappadocia, who may have written before Galen, used a near relative, heterocrania , “the other side of the head.” From there the word wore down in the mouths of Latin and French speakers. The unstressed first syllable dropped off, the c softened to a g , and hemicrania became migranea , then French migraine . Losing the front of a word has its own Greek name: aphaeresis , “a taking away.” Aphaeresis is also the term to separate a blood component from whole blood, the rest is usually returned to the body. GREEK · 2ND C. LATE LATIN POPULAR LATIN OLD FRENCH ENGLISH hēmi krania half + skull hemicrania borrowed as is he migranea first syllable lost; c → g migraine the French form megrim 14th century migraine re-borrowed, 18th c. hēmi- half · hemisphere, hemiplegia, hemithorax kranion skull · cranium, craniotomy, pericranium megrim later also “a whim”; “the megrims,” low spirits; in horses, a staggering fit Fig. 1 Half a head, then half a word. English took the word twice: once in the Middle Ages, where it became megrim , and again from French, where it kept the spelling we use now. English borrowed the modern spelling from French in the eighteenth century; an earlier medieval borrowing survives as megrim (Fig. 1). Physicians meanwhile kept the plainer Greek cephalalgia ( kephalē , head, and algos , pain), literally just “headache,” and the English-speaking public said “sick headache.” The half-head names went to someone else Here is the irony. The International Classification of Headache Disorders (ICHD-3) still uses the Greek word, but not for migraine. Paroxysmal hemicrania (described by Sjaastad and Dale in 1974) and hemicrania continua (Sjaastad and Spierings, 1984) are strictly one-sided headaches, grouped with cluster headache among the trigeminal autonomic cephalalgias, and defined in part by an absolute response to indomethacin. They earned the literal name. The name promises one side, but one side is just one feature among several to choose from. ICHD-3 · Migraine without aura , in brief At least five attacks lasting 4–72 hours untreated, with at least two of: unilateral location pulsating quality moderate or severe intensity aggravated by, or causing avoidance of, routine physical activity plus nausea and/or vomiting, or both photophobia and phonophobia, and not better explained by another diagnosis. The feature the name is built on is optional. So the name records an old observation, head pain that often favors one side, rather than a definition. A migraine can hurt on both sides, switch sides, or never hurt at all. The last case, typical aura without headache , has its own ICHD code. Before and after Many attacks begin well before the pain. Hours or even a day or two ahead, someone may yawn repeatedly, feel unusually tired, crave a food, notice a stiff neck, or struggle to concentrate. This is the prodrome . Pro- means before; Greek dromos is a running course. A prodrome “runs before.” That matters clinically. If someone craves chocolate and then develops a headache, chocolate may have triggered it, or the craving may tell us the attack had already begun. Both possibilities deserve more care than a universal forbidden-food list. Dromos is a busy root. After the pain comes the postdrome , the “migraine hangover” of fatigue and poor concentration. That word is a modern hybrid, Latin post bolted to Greek dromos . Purists call such crossbreeds barbarisms , in the good company of television and automobile . Word Parts Literally hippodrome hippos + dromos a course for horses dromedary dromas, running the running (fast-riding) camel palindrome palin + dromos running back again prodrome pro + dromos running before postdrome post (Latin) + dromos running after; a modern hybrid syndrome syn + dromos saved for the end Fig. 2 The running family. One Greek root for a racecourse gives us a camel, a word game, and three stages of illness. Fig. 3 Before, during, and after. Prodrome, aura, headache, postdrome. The phases overlap, and aura occurs in only some attacks. A breeze, a wall, and a sparkling darkness Aura is Greek for a breeze or a breath of air. The medical use began with epilepsy: Galen credited his teacher Pelops with the term, after a patient described a cold breeze rising up his leg before a seizure. Nineteenth-century physicians carried the word over to migraine, where it now means fully reversible visual, sensory, or language symptoms that build gradually, usually over 5 to 60 minutes. Most attacks have none. The most familiar aura has two names, both drawn from the same image. As it expands, the shimmering zigzag edge reminded Victorian observers of the star-shaped ramparts of a fortified town seen from above. English gave it the fortification spectrum ; Greek gave it teichopsia ( teichos , wall, and opsis , sight). In 1870 the physician Hubert Airy drew his own aura in sequence for the Royal Society; his father, the Astronomer Royal George Airy, had the same visions and called them “Norman arches.” Behind the zigzag lies a scotoma , from skotos , darkness: the blind patch the aura leaves behind. Put the words together and the common clinical term, scintillating scotoma , is a small oxymoron: a sparkling darkness. The leading explanation is cortical spreading depression , a slow wave of neuronal depolarization followed by suppressed activity, crossing the visual cortex at a few millimeters per minute. Depression here means a fall in electrical activity, as Leão meant when he named it in 1944, not a mood. Rarer auras distort size, so that objects or one’s own body seem too small or too large. In 1955 the psychiatrist John Todd named this Alice in Wonderland syndrome . Lewis Carroll had migraine; whether his auras shaped Alice is a pleasant speculation, not a finding. Fear that isn’t fear Photophobia and phonophobia join phōs (light) and phōnē (sound, voice) to phobos , fear. Patients are not afraid of the lamp. They find it painful or intolerable, so the accurate word would be aversion. The mechanism is not an injured optic nerve but convergence: in experimental work, retinal input and meningeal pain signals meet on the same thalamic neurons , so light turns up pain. The same logic gives osmophobia , aversion to smells ( osmē ). Allodynia is allos , other, plus odynē , pain: pain from something that should not hurt. During an attack, combing hair, wearing glasses, or a ponytail can hurt. It marks sensitization and is worth asking about. Nausea comes from Greek naus , ship: it was seasickness first. The same ship sails through nautical and astronaut . There is also a disputed but tempting theory that English noise descends, through Old French, from Latin nausea , in the sense of disturbance or annoyance. If so, the migraine patient lying in a dark room is avoiding two words from the same ship. Family matters The brain tissue itself has no ordinary pain receptors. The pain of migraine is carried from the meninges and their blood vessels by the trigeminal nerve. Latin trigeminus means born as triplets ( tri- , three, and geminus , twin, as in the zodiac’s Gemini, not the chatbot): one nerve, three branches. Its signals run through the brainstem and thalamus to cortex, and its terminals release CGRP, which amplifies and sustains the pain. The membrane those fibers live in is the dura mater , “hard mother,” with the pia mater , “tender mother,” lying on the brain beneath it. These terms come from Medieval Islamic clinicians who described anatomic relationships as parents and children; twelfth-century translators rendered the Arabic into Latin word for word. Other examples: abū kaʿb , “father of the ankle,” a folk name for mumps, and vessels described as sons of the root vessel. The meninges as a group come from Greek mēninx, membrane, also the root of meningitis. Drugs The term drug itself likely stems from French drogue , perhaps from Dutch droog , “dry,” for the dried herbs and roots that made up most remedies. An apothecary is simply a storekeeper: Greek apothēkē , a storehouse, is also the root of boutique and bodega . They would store the dried goods required for medical remedies. Pharmacy goes back to Greek phármakon , which meant remedy, poison, and charm all at once; only in the 19th century did the word come to mean the shop. Its relative pharmakeía could mean the use of drugs or sorcery, and the King James Bible translates it as “witchcraft.” Drug names are fossils. Several in migraine carry older theories inside them. Name Root What the name remembers serotonin serum + tonus Named in 1948 for a substance in blood serum that tightened blood vessels. The same molecule had been found in the gut a decade earlier and called enteramine . The name bakes in the old vascular theory of migraine. triptan tryptamine ← tryptophan ← trypsin A chain of borrowings back to Kühne’s 1876 name for a digestive enzyme. Dictionaries trace trypsin to Greek tripsis , rubbing; a 2024 historical analysis argues for thryptō , “I break in pieces,” which fits Kühne’s own explanation better. ergot Old French argot , cock’s spur The dark, spur-shaped fungal body on infected rye. Eating it caused ergotism, “St. Anthony’s fire.” Ergotamine was isolated from it in 1918. CGRP calcitonin gene-related peptide Calcitonin (1962) was named for the “tone” of calcium in blood. CGRP was found in 1982 as a second product of the same gene, made by alternative splicing in nerve tissue. The key migraine peptide is named after a thyroid hormone it barely resembles in function. -gepant, -mab CGRP receptor antagonist; monoclonal antibody Official name stems. A gepant blocks the receptor; a -mab is an antibody against CGRP or its receptor. Fig. 4 Fossils in the formulary. Where a drug works shows where the machine can be interrupted, not where the attack began. Triptans activate 5-HT 1B/1D receptors and constrict cranial vessels, which once seemed to confirm the vascular story written into serotonin’s name. But lasmiditan, a “ditan,” acts at 5-HT 1F without constricting vessels and still treats attacks, and gepants work without vasoconstriction too. The drugs show where an attack can be interrupted. They do not reveal where it started. Why keep a migraine-prone brain? An evolutionary tangent. Migraine is common and substantially heritable, and genome-wide studies show it is polygenic: many variants, each with a small effect. Something that common and that inherited invites the question of why selection kept it. Evolutionary lens Useful machinery can overshoot. Pain, nausea, light and sound avoidance, and the urge to lie still in the dark look a lot like sickness behavior , the conserved retreat mammals make when fighting infection. A migraine attack may recruit that old protective program far beyond what the situation needs. A high-gain nervous system has costs. A brain quick to notice change in light, sleep, hormones, or food may be good at detecting threat and keeping the body stable. The same sensitivity may be easier to push over a threshold. On this view the “benefit” was never the migraine itself; the migraine is the bill for the sensitivity. Mismatch, with a caveat. Screens, shift work, and caffeine cycling may push more people over the threshold. But fasting, lost sleep, heat, and menstruation are ancient, and so is migraine. Galen was describing it eighteen centuries ago. None of these stories is proven. They are good ways to think about the question, not answers. What would we call it if we discovered it today? Try building a name from what we now know. I suggest recurrent sensory and trigeminal syndrome . Each word earns its place, and each leaves something out. Word Captures Misses recurrent A repeating pattern of attacks A first attack can still be recognized sensory Light, sound, touch, smell, and aura Nausea and autonomic symptoms trigeminal The pathway for meningeal pain and CGRP The brainstem, thalamic, and cortical network; aura without pain syndrome Symptoms that travel together Any single mechanism or cause Fig. 5 · Recurrent sensory and trigeminal syndrome. More accurate than “half a head,” and nobody will ever say it. No replacement fits, because a name is a small box for a complicated disease. Migraine, the half-word for half a head, has at least survived two thousand years. The last word in that table is the one that fits best. We have met the hippodrome, where horses run; the palindrome, which runs back; and the prodrome, which runs before. Syndrome , syn + dromos , is things that run together, which is where the next entry begins. Disclaimer: This article is for educational purposes only. It is not medical advice, does not establish a clinician-patient relationship, and should not replace evaluation by a qualified healthcare professional. If you have urgent, severe, new, or otherwise concerning symptoms, seek appropriate medical evaluation. Discard Save Edit text"},{"url":"/medicolalia/no-2","title":"Things That Run Together — Medicolalia No. 2 | Gennady Gelman, MD","category":"Explore","text":"Things That Run Together — Medicolalia No. 2 | Gennady Gelman, MD Medicolalia · Radically examining medical terminology · No. 2 Things That Run Together By Gennady Gelman, MD In the last post, we met prodrome and postdrome in migraine: the things that run before an attack and the things that run after it. Now let’s look at the things that run together. That is a syndrome . Greek syndromē joins syn- , together, with the dromos we already know as running. Findings turn up in each other’s company often enough that we stop treating them as coincidence and start treating them as a pattern. We usually describe a syndrome as a constellation of signs and symptoms. Because this is an etymology series, we cannot use that word without opening it. Constellation is Latin: con- , together or with, and stella , star. Stars together. It is the same idea in a different language. Greek says syn- and Latin says con-; one gathers runnings, the other gathers stars. They do the same job, and it is worth learning to hear them that way. A quick tangent. Solar is Latin sol , sun; stellar is stella , star, the same star as in constellation. Our sun is a star named Sol, so every solar panel is, strictly speaking, stellar. I propose we start calling it stellar energy . But I might be alone in this. Back to our constellation. If a syndrome is a constellation, what are the stars? The usual answer is signs and symptoms. Signs are the objective findings. Symptoms are the subjective ones. But before we get too far ahead of ourselves, let’s look at those words. Symptom comes from Greek symptōma , a happening, something that befalls a person. Behind it is sympiptein , to fall together: piptein , to fall, and syn- once more, this time wearing an m . Synptom is hard to say, so the n bends toward the p that follows it. Linguists call this assimilation : ad- , toward, and similis , like, so to make like. The word does it to itself, since adsimilare became assimilare . It is the same prefix as in syndrome, caught twice in two words: running together and falling together. That falling root is one we already use at the bedside. In ptosis , something droops or descends: the eyelid in blepharoptosis , breast tissue in mammary ptosis . A symptom does not require anything to physically fall. It is the part of illness that happens to someone, which is why it landed on the side of what the patient experiences and reports. Sign looks like plain English and is Latin in plain sight: signum , a mark, token, or indication. A sign is a mark that someone reads. Its Greek counterpart is sēmeion , which gives us semiotics and semiology , the study of signs and what they mean. A clinician taking a history and examining a patient is doing semiology on a person . Notice the pattern from the opening repeating itself. Latin signum, Greek sēmeion: so much of medicine is duplicated thusly. So, symptoms are subjective and signs are objective. But what do we mean here? Subject and object do not sound like words with roots we would recognize. But you use the root every time you say eject : e- , out, and -ject , from Latin iacere , to throw. To eject is to throw out. Once you hear it, the family is everywhere. Each member is a direction plus a throw: Inject : throw in Reject : throw back Project : throw forward Interject : throw between Deject : throw down, which is why a dejected person is downcast Subject is sub- , under: throw under. Object is ob- , against or in the way of: throw against. The subjective is what lies under, inside the person having the experience. The objective is what is thrown in front of us, where anyone can run into it. Here philosophy steps in, because these two words have traded places . For the medieval scholastics, and still for Descartes, a thing existed subjectively when it existed in itself, as a real subject. It existed objectively when it existed as an object of thought, in the mind. That is nearly the reverse of how we use them now. The modern sense of subjective, existing in the mind, is attested from the early 1700s and was popularized by Kant and his contemporaries. Objective followed it across, though the older meaning remained the more familiar one in English until late in that century. So the throwing never changed direction. Philosophy reassigned which side faces the world. Every time we write an S and an O in a SOAP note, we are using a distinction that took centuries to settle into its present shape. The distinction concerns only how we obtain the information. It does not rank how real it is. A patient’s pain does not become less real because the clinician cannot feel it. The symptom is thrown under, held inside the patient. The sign is thrown out in front, where it can be read. Sometimes the things that run together remain a syndrome. Sometimes they run together to form what we call a disease or a disorder. The name usually ends in one of those three words, and they are not saying the same thing. Syndrome we have already obducted. I hope you don’t object to me using such an archaic term; I thought you would deduce from context that it means autopsy. The other two deserve the same treatment. Disease came through Old French desaise : lack of ease, discomfort, trouble. In English it was a word for how a person felt before it narrowed toward sickness in the late 1300s. That history leaves a small irony. We now speak comfortably of asymptomatic disease: a disease with no dis-ease in it, and nothing that has yet befallen the patient. Disorder is the most detached of the three: dis- and ordo , order undone. It describes an arrangement, not an experience. One might wonder whether chaos would serve better than disorder. They are similar words, but disorder sounds like a filing problem. Chaos is closer to what a condition does to a person’s life. Ask someone living with an attention or anxiety disorder which word fits their week better. The Greeks had the word ready. Khaos was not a mess. It was the abyss, that which gapes wide open, the emptiness before there was a world. The sense of utter confusion arrived much later, around 1600. Its opposite, at least since Ovid, is kosmos : order, good arrangement, and by extension adornment, which is why cosmetic is a relative. Pythagoras is said to have been the first to apply the word to the universe, perhaps meaning the starry firmament. Which brings us back to where we began. A constellation is a small piece of cosmos: stars that someone arranged into a shape and named. A syndrome is the same act performed on findings. We draw lines between the things that befall a patient and give the shape a name. Naming is how we pull a little order out of the chaos. It is tempting to rank syndrome, disease, and disorder: syndrome for a pattern we cannot yet explain, disease for one we can. But Alzheimer’s disease , attention-deficit/hyperactivity disorder (ADHD) , and Down syndrome do not occupy three levels on a ladder of scientific certainty. The last word in a diagnosis reflects history and convention as much as what we know. AIDS provides a particularly good counterexample. We know its cause, HIV, yet the word syndrome has survived. If syndrome meant “cause unknown,” we would have renamed it decades ago. We did not. More on that below. Yet another naming word belongs here: idiopathic . Greek idios means one’s own, private, particular to oneself. Pathos is suffering or disease. An idiopathic disease is a disease of its own. In older medical usage that meant a primary disease, one arising by itself and not as a consequence of something else. In ours it has come to mean a disease whose cause we cannot name. To a patient it may sound like a finding, but to the clinician it is closer to a confession. Many people likely hear idiotic inside it, and suspect the word is a quiet insult to the disease, the patient, or the doctor. The suspicion is half right. The two words share a common ancestor, but not a meaning. Greek idiōtēs was simply the private person: someone who held no office and took no part in public affairs. By extension he was the layman, the one without professional skill. It was not yet an insult, although the Greeks could already use it patronizingly. Then the word began to fall. Latin idiota was an ordinary person or layman, and in Late Latin an uneducated or ignorant one. Old French kept the ignorance. By the time the word reached English in the early 1300s, it could mean a person incapable of ordinary reasoning. Private, then unskilled, then ignorant, then the slur. Idiopathic took the other branch of the same root: the privacy, not the insult. The disease is not idiotic. It is private. It keeps its cause to itself. The same idios gives us idiom , a turn of phrase particular to one language, and idiosyncrasy , which entered English around 1600 as a medical term for an individual’s physical constitution. Open it and an old friend is inside: idios plus synkrasis , a mixing together. One’s own particular blend. We keep being brought back together by the prefix syn-; perhaps it is written in the stars. Seven syndromes, seven naming lessons Idiopathic is where a name admits uncertainty. Sometimes we learn more, and a diagnosis acquires a new name. Sometimes we keep the old one. And sometimes naming changes for reasons that have little to do with discovering a mechanism. The following seven syndromes show just how differently these stories unfold. An eponym connects a name with a person after whom something is named. Greek epōnymos joins epi- , upon or after, with onyma , a form of onoma , name. The name family is familiar once you notice it: anonymous , without a name; pseudonym , a false or assumed name; and synonym , a name together, where syn- turns up yet again. An eponym can be compact, memorable, and an invitation to history. But a surname says little about anatomy or mechanism. As our understanding changes, we sometimes replace a person’s name with words that describe what we have learned. Stein–Leventhal Stein and Leventhal’s 1935 report grouped menstrual abnormalities with enlarged polycystic ovaries, and the condition became Stein–Leventhal syndrome, a name that told most people nothing. It was later renamed polycystic ovary syndrome (PCOS) . Open it up: poly- means many; cyst comes from a Greek word for a sac; ovary comes from Latin ovum , egg. The name was descriptive, but the description was misleading: the ovarian features concern follicles rather than abnormal cysts, and the condition extends far beyond the ovaries. On May 12, 2026, an international consensus initiative announced a new name: polyendocrine metabolic ovarian syndrome (PMOS) , with full implementation planned in the 2028 international guideline . Endocrine means secreting within; metabolic draws attention to the body’s chemical processes. The name no longer asks us to look only at cysts that may not even be present. It asks us to consider a broader endocrine and metabolic condition. Even a descriptive name is a claim about what we understand. As we learn more, the name has to adapt. Churg–Strauss Churg–Strauss syndrome became eosinophilic granulomatosis with polyangiitis (EGPA) . That is a mouthful, but it is also a pathology lesson: eosinophilic points to a type of white blood cell; granulomatosis to organized inflammatory collections; and polyangiitis to inflammation of many vessels. Asthma and elevated eosinophils often accompany the disease. There is even a little history of microscopy in the name. Eosinophils took their name from eosin , the stain their granules take up. Granulum is Latin for a little grain; angi- comes from Greek for vessel. A surname has been traded for a set of biological clues. And there is a sunrise inside the name: eosin comes from Greek Ēōs , dawn, a reference to its color. Homer’s dawn was rosy-fingered, and so is an eosin stain. The word is older than Greek. Sanskrit has it as Uṣas , the Vedic goddess of dawn; Latin, as Aurora . English kept it as east , the direction dawn comes from, and Easter , possibly named for Ēostre, a dawn goddess of its own. A stain named for dawn helped name a cell, which helped name a disease. Kartagener Kartagener syndrome described a memorable trio: chronic sinus disease, bronchiectasis , and situs inversus , the mirror-image arrangement of internal organs. But a surname could not explain why chronic respiratory problems and reversed organ positions should run together. The answer involved cilia , the microscopic projections whose movement clears mucus and whose developmental functions help establish left and right. Primary ciliary dyskinesia (PCD) describes the broader mechanism: dys- , abnormal; kinesis , movement. The older name remains useful for the particular presentation with situs inversus, but PCD explains why some patients have the lung findings without reversed organs. Down syndrome Down syndrome takes its name from John Langdon Down, whose 1866 clinical description recognized a recurring pattern but framed it with mistaken racial assumptions. Only much later did scientists discover the chromosomal cause : extra chromosome 21 material, most often a full third copy. Trisomy 21 says something that the eponym cannot: tri- , three, and -somy , a chromosome-count construction ultimately tied to Greek sōma , body. Yet Down syndrome has not simply been renamed. Both terms survive because one names a clinical syndrome and the other reveals a common genetic explanation. Reiter syndrome One name changed for a less comfortable reason. The old “ Reiter syndrome ” linked arthritis , urethritis , and conjunctivitis to Hans Reiter, whose involvement in Nazi medical atrocities made continuing the honorific indefensible. That is a moral objection, not merely a desire for a more descriptive term. Reactive arthritis is also a more useful clinical name. It points toward joint inflammation that follows an infection elsewhere, often in the gastrointestinal or genitourinary tract. The familiar three-part presentation is not required; the new name directs us to ask what preceded the arthritis. Reactive tells us to look for a relationship between events. Arthritis names inflammation of a joint. This is one case in which clearer language and an ethical correction point in the same direction. AIDS Acquired immunodeficiency syndrome (AIDS) sounds like a placeholder from an era before we knew what caused it. Yet the cause, HIV, has been established for decades, and AIDS remains a distinct term for advanced HIV infection. In the CDC’s surveillance classification , it corresponds to stage 3, which can be defined by a sufficiently low CD4 count or an AIDS-defining illness. A patient need not be visibly ill to meet that definition. The old name has historical weight, while the explicit stage tells us more precisely what we mean. Metabolic syndrome Metabolic syndrome is the most literal return to our constellation. We draw a line around several findings: increased waist circumference, high blood pressure , elevated triglycerides, low HDL cholesterol, and elevated blood glucose. Usually, three of the five are enough to satisfy the clinical definition. They tend to travel together, and together they help identify cardiometabolic risk. But there is no single germ, gene, or lesion that makes the entire grouping inevitable. Insulin resistance is often implicated; lifestyle, genetics, and other influences matter. The word syndrome is doing exactly the work it was built to do: collecting features that run together even when one explanation cannot encompass every patient. What the seven tell us These seven have not all been “renamed,” and that is the point. One name moved from anatomy toward physiology (PMOS). Another became a pathology lesson (EGPA). One old syndrome became a recognizable subset of a larger mechanism (Kartagener). One eponym lives alongside a chromosomal explanation (Down). One lost its honorific for ethical reasons (Reiter). Another name persisted despite an established cause (AIDS). And one remains an intentionally practical constellation (metabolic syndrome). Words preserve a discovery, a hypothesis, a convention, or a moral judgment. They do not necessarily keep pace with knowledge. The tropic table A constellation is stars someone arranged into a shape. A syndrome is findings someone arranged into a pattern. But what if we arranged the questions instead? The periodic table is named for periods — rows where electron shells repeat. The body does not work in periods. It works in axes: chains of steps, each with a direction. A tropic table would be a table of turnings: Greek tropos , a turn. The thyroid axis already speaks this language. TSH is also called thyrotropin , the hormone that turns toward the thyroid; TRH is thyrotropin-releasing hormone. Most findings are a turning, toward excess or toward lack. Leukocytosis turns toward excess. Leukopenia turns toward lack. Every pathway, every step, every direction it can deviate. Take the thyroid as an example. Draw the pathway: TRH to TSH to T4 to T3 to receptor . Then ask three questions at every step: what if this step runs too fast or too much, too slow or too little, or is missing or breaks entirely? Lay the steps across and the questions down, and you have a grid. For the thyroid, the grid is nearly full. High TSH with low T4 is primary hypothyroidism . Low TSH with high T4 is primary hyperthyroidism, most often Graves’ . High TSH with high T4 is a TSH-secreting tumor . Low TSH with low T4 points upstream. The conversion door — T4 to T3 — has its own name: low T3 syndrome , seen in starvation and critical illness. The receptor door is thyroid hormone resistance : the gland works, the hormones work, but the body cannot hear them. The grid constrains itself. High TSH and high T4 together is a contradiction unless the tumor door or the receptor door is open. Like a Sudoku, you cannot fill every square independently. The squares talk to each other. And some squares are empty because we have not looked. The UGT1A1 fast variant clears bilirubin so efficiently it also clears more of irinotecan ’s active form. Whether that blunts the drug, nobody has shown. The mechanism is known. The disease is not. The square is there; nobody has walked through the door. Dmitri Mendeleev’s empty squares predicted elements that did not exist yet. Medicine’s empty squares should predict doors nobody has opened. The table is not a map of what we know. It is a map of what we have not asked. The name is where understanding starts. It should not be where it stops. This article explores medical language and reasoning; it is not a diagnostic checklist or individualized medical advice. ← No. 1: Migraine All Medicolalia posts"},{"url":"/professional/resources","title":"Clinical Reference Library - Gennady Gelman","category":"Explore","text":"Clinical Reference Library - Gennady Gelman Gennady Gelman, MD ← Students & Colleagues Search site Students & Colleagues Clinical Tools & Resources A practical directory of clinical AI, calculators, guidelines, apps, lab pearls, patient resources, and frequently referenced articles. Last reviewed September 2026 All types Website type Calculator type App type Guideline type Article type Clear All AI Calculators Lab Pearls Guidelines Pharmacy Nutrition & Lifestyle Vaccines & Travel Mental Health Pediatrics Women&#x27;s Health Geriatrics Patient & Community Articles All resources Enable JavaScript to search this directory, or browse the clinical library . No resources match those filters. Know a resource worth adding? Send the resource name, link, and a quick note about why it belongs here. The email draft is pre-filled for you. Submit a Resource → This is a curated educational directory, not a substitute for clinical judgment or local policy. External resources may change; verify current guidance before use. ChatGPT AI Website OpenAI's general-purpose AI assistant for answering questions, drafting, and summarization. Anthropic Claude AI Website Anthropic's AI assistant focused on safety, reasoning, and long-context analysis. Google Gemini AI Website Google DeepMind's AI assistant, tightly integrated with Google Search and Workspace. Microsoft Copilot AI Website Microsoft's AI assistant integrated across Bing, Edge, Windows, and Microsoft 365. Perplexity AI Website AI-powered answer engine with real-time web access and inline citations. Google NotebookLM AI Website AI research assistant that organizes, summarizes, and answers questions across uploaded documents. Grok AI Website xAI's conversational AI assistant, also integrated with X. OpenEvidence AI Website Clinician-only AI for searching and summarizing medical literature; partnered with NEJM and JAMA. Doximity GPT AI Website HIPAA-compliant clinician chatbot with physician-verified answers, drug reference, and prior-auth letter drafting. Linus Health AI App iPad-based, AI-augmented digital cognitive assessment platform for early detection of cognitive impairment in primary care. Brook Health AI App AI-augmented remote patient monitoring and health coaching platform for chronic conditions, including diabetes and hypertension. DAX Copilot (Microsoft / Nuance) AI App Ambient documentation embedded natively in Epic; drafts notes, referral letters, and after-visit summaries. NEJM AI AI Article Peer-reviewed New England Journal of Medicine publication focused on AI in healthcare and medicine. JAMA AI AI Article JAMA Network collection covering AI advancements, evaluation, and research in healthcare. MDCalc Calculators Calculator Comprehensive library of medical calculators, clinical equations, and decision-support tools. USPSTF Prevention TaskForce (ePSS) Calculators Website Evidence-based USPSTF preventive care recommendations searchable by patient age, sex, and risk factors. AHA PREVENT Calculator Calculators Calculator Estimates 10- and 30-year risk of total cardiovascular disease, including heart failure, for ages 30–79. QRISK3 Calculators Calculator Open-access 10-year CVD risk calculator that includes CKD, RA, SLE, AF, and severe mental illness. FRAX Calculators Calculator 10-year fracture risk calculator integrating clinical risk factors with or without BMD. Aspirin Guide Calculators Calculator Assists clinicians in shared decision-making about aspirin for primary prevention. TheNNT Calculators Website Evidence-based reviews of therapies organized around Number Needed to Treat and Number Needed to Harm. SEER Cancer Stat Facts Calculators Website NCI statistics on cancer incidence, mortality, and survival by site and stage. MME Opioid Conversion Calculator (MDCalc) Calculators Calculator Converts opioid dosages to morphine milligram equivalents for safe prescribing. American Family Physician (AFP) Guidelines Website AAFP's peer-reviewed journal providing continuing medical education for family physicians. FamilyDoctor.org Guidelines Website AAFP's patient-facing health information site, organized by topic. Family Practice Notebook Guidelines Website Concise medical reference for primary care and family medicine, actively maintained. Radiopaedia Guidelines Website Free radiology reference and case library covering imaging findings, diagnoses, and teaching cases. 2026 ACC/AHA Dyslipidemia Guideline Guidelines Guideline 2026 dyslipidemia guideline with universal Lp(a) screening, lower LDL targets, and lifecourse emphasis. Diabetes Care — Standards of Care 2026 Guidelines Guideline ADA's annual Standards of Medical Care in Diabetes, 2026 supplement. ADA Standards of Care App Guidelines App Living ADA Standards with interactive tables and algorithms. GOLD 2026 COPD Report Guidelines Guideline Global COPD strategy with updated disease activity, biologics, and escalation guidance. GINA 2026 Asthma Strategy Guidelines Guideline Global asthma strategy with updated primary-care exacerbation flowcharts and biologic decision tree. KDIGO CKD Guideline (2024) Guidelines Guideline CKD evaluation and management guideline including cystatin C, SGLT2 inhibitors, and statin use. GoodRx Pharmacy Website Compares local cash prices for prescription medications and provides coupons. LactMed (Drugs and Lactation Database) Pharmacy Website NIH database on maternal medications, lactation, and the breastfed infant. CDC Opioid Prescribing Guideline (2022) Pharmacy Guideline CDC clinical practice guideline for prescribing opioids for pain. Healthy Eating Plate Nutrition & Lifestyle Website Harvard T.H. Chan School of Public Health's science-based visual guide to healthy eating. MyFitnessPal Nutrition & Lifestyle App Calorie counter and diet tracking app for weight management and macro tracking. NIDDK Body Weight Planner Nutrition & Lifestyle Calculator NIH tool that predicts weight changes based on diet and physical activity inputs. The Daily Dozen Checklist Nutrition & Lifestyle App Tracks daily servings of food groups based on Dr. Greger's nutrition recommendations. Fastic Nutrition & Lifestyle App Intermittent fasting and holistic wellness app with tracking and education. Fooducate Nutrition & Lifestyle App Nutrition scanner and diet tracking app providing food-quality grades and analysis. CDC Travel Health (Yellow Book) Vaccines & Travel Website Destination-specific health and vaccine recommendations for international travel. CDC Vaccine Schedules App Vaccines & Travel App Quick access to pediatric, adult, and catch-up immunization schedules for clinicians. PneumoRecs VaxAdvisor Vaccines & Travel App CDC tool for determining pneumococcal vaccine recommendations by patient profile. Insomnia Coach Mental Health App Free VA CBT-I-based self-care app with a guided training plan, sleep diary, and tools for managing insomnia. PHQ & GAD Screeners Mental Health Website Official source for PHQ-9, GAD-7, PHQ-15, and related validated screeners. AUDIT / AUDIT-C (WHO) Mental Health Website Alcohol use screeners with primary-care implementation guidance. KidsHealth Pediatrics Website Nemours-backed parent, child, and teen-facing site for children's health and parenting topics. HealthyChildren.org Pediatrics Website AAP-backed, ad-free parent-facing site covering ages and stages, safety, and nutrition. Bright Futures (AAP) Pediatrics Guideline AAP periodicity schedule, anticipatory guidance, and visit forms for ages 0–21. CDC's Milestone Tracker App Pediatrics App Helps parents track and document developmental milestones from age 2 months to 5 years. Massachusetts Community Water Fluoridation Status Pediatrics Website State resource detailing fluoridation status of Massachusetts public water systems. Bedsider Birth Control Support Network Women's Health Website Patient-facing resource on contraceptive options, side effects, and access; provider portal also available. ACOG Clinical Women's Health Guideline ACOG Practice Bulletins, Committee Opinions, due-date calculator, and immunization tools. Reproductive Health Access Project Women's Health Website Free multilingual patient fact sheets and clinician guides for contraception, EC, and miscarriage management. ASCCP Management Guidelines Women's Health Guideline Risk-based management guidelines for abnormal cervical cancer screening results. AGS Beers Criteria Geriatrics Guideline Standard reference for potentially inappropriate medications in adults aged 65 and older. Deprescribing.org Geriatrics Website Evidence-based deprescribing algorithms with patient handouts. Ada Patient & Community Website AI-powered patient-facing symptom checker for personalized health assessments. findhelp.org Patient & Community Website National search for free and reduced-cost social care services, including food, housing, transportation, and financial assistance. Clinical Problems Caused by Obesity Articles Article Comprehensive open-access Endotext chapter on the medical consequences of obesity. Effects of Intermittent Fasting on Health, Aging, and Disease Articles Article de Cabo & Mattson review of the metabolic, aging, and disease effects of intermittent fasting. Serial Bone Density Measurement for Osteoporosis Screening Articles Article Gourlay et al. on the appropriate interval between repeat DXA scans in older women. Radiation-Induced Breast Cancer from Digital Mammography Screening Articles Article Modeling study of radiation-induced cancer incidence and mortality from screening mammography. SELECT Trial — Semaglutide and Cardiovascular Outcomes Articles Article Semaglutide 2.4 mg reduced major adverse cardiovascular events by 20% in non-diabetic adults with obesity and CVD. SURMOUNT-1 — Tirzepatide for Obesity Articles Article Tirzepatide produced up to about 22.5% weight loss in adults with obesity without diabetes over 72 weeks. FLOW Trial — Semaglutide in CKD with T2D Articles Article Semaglutide reduced major kidney outcomes by 24% and cardiovascular death by 29% in T2D with CKD. Recombinant Zoster Vaccine and Dementia Risk Articles Article Two doses of recombinant zoster vaccine were associated with a 51% lower risk of dementia in adults aged 65 and older."},{"url":"/tools/cv-risk","title":"Cardiovascular Risk Calculator - Gennady Gelman","category":"Clinical tools","text":"Cardiovascular Risk Calculator - Gennady Gelman CV Risk Decision Tool v30.3 Clinician use only • AHA PREVENT + race-free MESA CAC risk + 2026 dyslipidemia decision support PREVENT is calculated in your browser. If an actual CAC score is entered, the MESA-required variables are sent to the official MESA race-free calculator service. 1. Paste chart data Parse & calculate Clear 2. PREVENT inputs Age Biological sex Select Female Male Systolic BP (mmHg) eGFR (mL/min/1.73m²) PREVENT requires a valid eGFR. Total cholesterol (mg/dL) Values &lt;130 are floored to 130 for PREVENT only. MESA uses the entered value. HDL-C (mg/dL) LDL-C (mg/dL) Used for treatment guidance. Never altered. Triglycerides (mg/dL) BMI (kg/m²) Lp(a) (nmol/L) Values reported as &lt;X are parsed as X for threshold logic (e.g. &lt;10 → 10). ApoB (mg/dL) hsCRP (mg/L) HbA1c (%) Optional PREVENT predictor. UACR (mg/g) Optional PREVENT predictor. SDI decile (1-10) Optional PREVENT predictor. ZIP to SDI is not guessed. Diabetes Unknown / not entered No Yes Current cigarette smoking Unknown / not entered No Yes Antihypertensive treatment Unknown / not entered No Yes 3. Clinical context and CAC Prevention setting Primary Secondary Secondary - very high risk PREVENT and MESA are primary-prevention risk calculators. Actual CAC score (Agatston) Enter 0 when CAC is zero. Any numeric value, including 0, can trigger race-free MESA if the other required inputs are known. If exact CAC is not available Not known Reported CAC 0 Reported CAC 1-99 Reported CAC ≥100 / ≥75th percentile Qualitative CAC can inform treatment guidance, but MESA is not calculated without an actual Agatston score. Family history of heart attack for MESA Unknown / not entered No Yes MESA definition: heart attack in a parent, sibling, or child. Pregnancy / reproductive status Not specified / not applicable Not pregnant or lactating Planning pregnancy Pregnant Lactating Current antihypertensive regimen (optional) Risk-enhancing / special-population factors HIV CKD stage 3-4 Familial hypercholesterolemia Family history premature ASCVD Chronic inflammatory disease South Asian / Filipino ancestry Preeclampsia / premature menopause 4. Lipid treatment context Prior statin intolerance Prior ezetimibe intolerance Current lipid-lowering medication Unknown / not entered None Statin (drug/dose not specified) Atorvastatin Rosuvastatin Simvastatin Pravastatin Lovastatin Ezetimibe Evolocumab (Repatha) Alirocumab (Praluent) Inclisiran (Leqvio) Enlicitide (oral PCSK9) Bempedoic acid Combination / other Dose / regimen Current statin use for PREVENT Unknown / not entered No Yes PREVENT uses current statin use. Nonstatins alone do not count as statin use. Calculate / update Clinician result PREVENT risk profile — 10-year predicted risk Total CVD — ASCVD + heart failure composite ASCVD — MI / coronary death / stroke Heart failure — PREVENT-HF PREVENT-Age — Base-equation metric Equivalent heart/risk age derived from 10-year PREVENT-CVD. 30-year predicted risk Total CVD — Available through age 59 ASCVD — Available through age 59 Heart failure — Available through age 59 Idealized risk-factor scenario Best-case from the modifiable factors shown below Same age and nonmodifiable context. This is a hypothetical PREVENT recalculation for teaching, not a causal treatment-effect estimate. — 10-y total CVD — 10-y ASCVD — 10-y heart failure What if? Only applicable factors are offered. Combine as many as you want. Important: “BP controlled without medication” models an idealized phenotype. It is not a recommendation to discontinue antihypertensive therapy. BMI is not a direct term in the 10-year PREVENT-ASCVD equation, but it is a direct term in PREVENT-HF and therefore changes can affect the broader outcome suite. CVD, ASCVD, and HF are modeled separately; ASCVD + HF can numerically exceed total CVD. 30-year estimates apply only through age 59. PREVENT-Age always uses the base 10-year PREVENT-CVD equation even when an enhanced optional-predictor model is selected. CAC-informed coronary risk Race-free MESA 10-year CHD risk Using actual CAC — Without considering CAC — Same MESA risk-factor profile, excluding the CAC result. MESA predicts CHD, not the same endpoint as PREVENT ASCVD or total CVD. Do not compare the percentages as if they were interchangeable. What to focus on Clinical priority — Priority ranking is heuristic decision support based on current treatment gaps and risk context. It is not an individualized causal treatment-effect estimate. Color-coded clinical context Lipids & risk markers Treatment support Decision summary Additional clinician context Effect of Lp(a) The March 13, 2026 ACC/AHA multisociety dyslipidemia guideline (Table 4) describes an observational association between Lp(a) and ASCVD relative risk, compared with the population median of 20 nmol/L. These UK Biobank estimates are a general guide and may differ in other populations. Patient Lp(a) — Illustrative ASCVD relative-risk factor — Illustration only — not a validated PREVENT probability adjustment. Multiplying an original PREVENT score by an observational relative-risk factor does not produce a calibrated personal event probability or a guideline-endorsed PREVENT recalculation. PREVENT already reflects a population with varying Lp(a). The official scores and categories above, treatment support, and patient letter continue to use the original PREVENT results. Original PREVENT-ASCVD · 10 years — Official original score, repeated unchanged. Illustrative multiplied score · 10-year ASCVD — This ASCVD association is not applied to heart failure, total CVD, PREVENT-Age, MESA, or 30-year results. No validated adjustment for those outputs is implied. How the illustrative factor is selected Table 4 lists reference Lp(a) &lt;75 nmol/L; 1.2× at 75–124; 1.4× at 125; 2× at 250; 3× at 350; and 4× at 430 nmol/L. For this illustration, values between the listed anchors use the lower anchor: 125–&lt;250 → 1.4×, 250–&lt;350 → 2×, 350–&lt;430 → 3×, and ≥430 → 4×. These stepwise bands are this tool’s approximation, not exact guideline cutoffs for a continuous biological relationship. Below 75, 1× is a display convention; no downward adjustment is made. Values above 430 are not extrapolated beyond 4×. Only nmol/L is accepted here; do not enter mg/dL or use a fixed unit conversion. A chart value reported as &lt;X or &gt;X is handled by the existing parser as X; confirm the actual result before interpreting a factor. Source: 2026 ACC/AHA multisociety dyslipidemia guideline, Table 4 . Patient output Patient letter Patient output uses PREVENT for overall cardiovascular risk. MESA stays clinician-facing because it predicts a different coronary endpoint. Guidelines & supporting evidence Read more: evidence behind this tool These are the principal guidelines, derivation studies, and validation studies supporting the calculations and decision pathways used above. Links open the original publication or official project page. Current guidelines 2026 ACC/AHA Multisociety Dyslipidemia Guideline Published March 13, 2026. Introduces PREVENT-based treatment thresholds, LDL and non-HDL goals, risk enhancers, and selective CAC reclassification. 2025 AHA/ACC High Blood Pressure Guideline Supports contemporary BP thresholds, treatment decisions, and integration of predicted cardiovascular risk. Official AHA PREVENT Calculator Clinical implementation of 10- and 30-year CVD, ASCVD, and heart-failure risk estimates, including PREVENT-Age. PREVENT models Development and Validation of the AHA PREVENT Equations Khan et al., Circulation, 2024. Derivation and validation of the sex-specific, race-free PREVENT equations in more than 6 million adults. External Validation of PREVENT Scheuermann et al., JAMA Network Open, 2024. Evaluates discrimination and calibration in a nationally representative US cohort. PREVENT Risk Age Equations Krishnan et al., JAMA Cardiology, 2025. Describes the PREVENT-Age communication metric displayed in this tool. Coronary calcium & MESA CAC Added to the PREVENT-ASCVD Equations Huang et al., JAMA, 2026. Finds that CAC provides its greatest reclassification value in borderline- and intermediate-risk patients. Derivation and Validation of the MESA CAC Risk Score McClelland et al., JACC, 2015. Establishes the 10-year CHD model using traditional risk factors with and without CAC. Official Race-Free MESA Risk Score MESA’s current race-free calculator and project description. The model excludes race/ethnicity and related interaction terms. For clinician use only. Decision support, not a substitute for clinical judgment. PREVENT is used for primary prevention. Established ASCVD follows the secondary-prevention pathway. Pregnancy and lactation require medication-specific review. PREVENT engine: pinned public implementation of the AHA PREVENT equations. Race-free MESA: official MESA score-norace service when CAC is entered. Clinical tool developed by Gennady Gelman, MD"},{"url":"/tools/diabetes-type","title":"Diabetes Type Evidence Tool - Gennady Gelman","category":"Clinical tools","text":"Diabetes Type Evidence Tool - Gennady Gelman Clinician decision support · v1.0 ← Clinical tools What type of diabetes does the evidence support? Combine islet autoantibodies, contextualized C-peptide, and clinical clues. The result is an explainable phenotype assessment—not a diagnosis or a mathematically validated probability. Evidence Use “not tested” rather than treating missing data as negative. Islet autoantibodies Select the laboratory interpretation using that assay’s reference range. Beta-cell reserve C-peptide ng/mL nmol/L pmol/L Collection context Unknown Random / within 5 hours of food Fasting Paired glucose (mg/dL) Kidney function Unknown eGFR ≥30 eGFR &lt;30 / kidney failure Recent hyperglycemic emergency No / more than 2 weeks ago DKA or hyperosmolar emergency within 2 weeks Unknown Clinical context Most recent A1C (%) Currently treated for diabetes Unknown No Yes Currently using insulin Unknown No Yes When insulin was first required Unknown / not applicable Never used Within 6 months of diagnosis More than 6 months after diagnosis Age at diagnosis Years since diagnosis BMI at/near diagnosis DKA at presentation Unknown No Yes Exogenous insulin before IAA test Unknown No Yes Family history pattern Unknown / none First-degree relative with type 1 diabetes First-degree relative with type 2 diabetes Diabetes in successive generations, often diagnosed young Maternal-line diabetes with deafness or other mitochondrial features Pancreatic disease or resection No known pancreatic disease Chronic pancreatitis, pancreatic cancer, cystic fibrosis, hemochromatosis, or pancreatic resection Unknown Interpret evidence Reset Interpretation Updates when you select “Interpret evidence.” Enter the available results, leaving unmeasured items as not tested . Interpretive rules, limitations, and sources Autoantibodies: GAD65 is the preferred first test in adults; if negative, IA-2 and/or ZnT8 add sensitivity. Multiple confirmed islet autoantibodies strongly support autoimmune diabetes. A negative panel does not exclude type 1 diabetes. C-peptide: This tool converts results to nmol/L. A nonfasting value below 0.20 nmol/L supports severe insulin deficiency, 0.20–0.60 nmol/L is an overlap zone, and above 0.60 nmol/L indicates substantial endogenous secretion. Interpretation depends on glucose, timing, diabetes duration, kidney function, and recent metabolic decompensation. A1C and treatment: A1C describes recent glycemic exposure but does not distinguish diabetes type. Current treatment— including insulin—may reflect severity, clinician choice, or disease duration. The interval from diagnosis to insulin requirement is more discriminating than insulin use alone. Insulin autoantibodies: IAA is most interpretable before exogenous insulin exposure. Antibodies measured after insulin treatment may reflect therapy rather than spontaneous beta-cell autoimmunity. Sources: ADA Standards of Care 2026: Diagnosis and Classification ; ADA/EASD adult type 1 diabetes consensus report . Clinician use only. This tool is educational decision support, not a diagnostic device. It cannot exclude ketosis-prone diabetes, medication-induced diabetes, endocrinopathies, genetic syndromes, or other secondary causes. Do not delay insulin when clinically indicated. No entered data is transmitted or stored. © Gennady Gelman, MD"},{"url":"/tools/immunizations","title":"Pediatric Vaccine Guidance - Gennady Gelman","category":"Clinical tools","text":"Pediatric Vaccine Guidance - Gennady Gelman V Pediatric Vaccine Guidance Routine CDC schedule review for healthy children • Works entirely offline Version 1 scope: routine schedule screening only. Complex catch-up schedules, risk-based recommendations, contraindications, COVID-19, RSV products, and travel vaccines require separate clinical review. Patient information Epic SmartPhrase template DOB: @DOB@ @IMM@ Copy SmartPhrase Paste Epic immunization history Information is processed in this browser only. Nothing is uploaded, transmitted, or saved. Parse & analyze Clear Date of birth DOB is filled automatically when it appears in the pasted Epic text. You can also enter or correct it here. Optional clinical context Any selection triggers clinical review; this version does not calculate risk-based schedules. Immunocompromised Asplenia / sickle cell HIV Heart / lung disease Kidney disease Liver disease Cochlear implant / CSF leak Pregnancy Prior severe reaction International travel ✓ Your vaccine roadmap will appear here Enter DOB, paste the immunization history, and select Analyze. Clinician use only • Routine ruleset prototype 0.3 • CDC schedule • CDC catch-up schedule"},{"url":"/tools/lab-analyzer","title":"Clinical Lab Pattern Analyzer - Gennady Gelman","category":"Clinical tools","text":"Clinical Lab Pattern Analyzer - Gennady Gelman Clinician tool · prototype Clinical Lab Pattern Analyzer Paste a lab block. The tool normalizes common labels, calculates derived values, and surfaces clinically coherent patterns with explicit caveats. Input Works best with one result per line, but also recognizes compact BMP/CBC-style text. Epic SmartPhrase template Age: @AGE@ Sex: @LEGALSEX@ Labs:@GETLABS(3M,2)@ Copy SmartPhrase Age (optional if pasted) Sex at birth (optional if pasted) Not provided Female Male Fasting status Unknown Fasting Not fasting Qualifying dialysis in prior 7 days Unknown No Yes Parse SmartPhrase Clear Relationships & patterns Calculations are separated from contextual clinical inferences. Paste Epic SmartPhrase output and select Parse SmartPhrase . Calculation reference guide and sources Selected primary or authoritative references supporting the formulas and interpretive guardrails used in this tool. Individual result cards include the most relevant source on their reverse side. KDIGO 2024 CKD guideline — eGFR and albuminuria categories Hillier et al. — glucose-adjusted sodium Adjusted calcium limitations review — albumin-adjusted calcium Protein-gap screening study — protein gap and monoclonal gammopathy Mentzer index report — microcytosis screening ratio Original FIB-4 validation — liver-fibrosis risk stratification HRSA/OPTN MELD calculator — MELD 3.0 ADA Standards of Care 2026 — A1c and glycemia Original HOMA model — HOMA-IR QUICKI validation — insulin sensitivity TyG validation — triglyceride-glucose index AHA/ACC cholesterol guideline — lipid relationships International PCOS guideline — limits of LH/FSH interpretation Alzheimer’s Association guideline — blood biomarker interpretation Clinician use only. This tool provides clinical decision support and is not a diagnostic device. It does not know the full history, symptoms, medications, baseline values, timing, local reference ranges, or specimen quality. Verify every parsed value and apply clinical judgment. v1.8 · Rules are intentionally conservative. No patient data leaves this page. For questions or comments, contact me@gennadygelman.com ."},{"url":"/tools/raf-calculator","title":"2026 RAF Calculator - Gennady Gelman","category":"Clinical tools","text":"2026 RAF Calculator - Gennady Gelman CMS-HCC V28 RAF Calculator + Problem List Parser 2026 Medicare Advantage model · Parses Epic-style problem lists · Official final CMS mappings and coefficients ◉ Offline & local — entered data never leaves this file Raw model estimate: This calculates the CMS-HCC V28 model score using the selected segment. It does not apply normalization, the MA coding-pattern adjustment, plan-specific blending, frailty, ESRD, or payment calculations. Clinician and analytic use only. Patient & model inputs Epic SmartPhrase template DOB: @DOB@ AGE: @AGE@ SEX: @LEGALSEX@ Problems: @PROB@ Copy SmartPhrase Demographics Paste patient snapshot or problem list The parser recognizes common Epic formatting and extracts DOB or age, sex, problem-list terms, and any ICD-10-CM codes that are present. Problem-list text is not coding documentation. Only exact or specifically curated matches are counted automatically; ambiguous terms are displayed for review and do not increase the score. Date of birth Age on 02/01/2026 Sex Select… Male Female Original reason for Medicare entitlement (OREC) Old age / OASI Disability / DIB ESRD Disability and ESRD Enrollment segment Enrollment type Continued enrollee New enrollee Community / institutional status Community — no Medicaid Community — partial-benefit dual Community — full-benefit dual Institutional For patients under 65, community coefficients automatically use the disabled segment. New enrollee model Standard MA SNP Medicaid No Yes Long-term institutional Medicaid indicator Advanced: add confirmed ICD-10-CM codes Confirmed ICD-10-CM codes These codes bypass free-text matching. Codes may be separated by spaces, commas, or lines; duplicates are removed. Parse & calculate Load sample Clear Paste demographics and an Epic problem list The result will show the parsed problems, confirmed mappings, active HCCs, hierarchy suppression, and every coefficient used. Raw model score — — Demographic — age, sex, status HCCs — — Interactions — including HCC count Print report Copy summary HCC results Score detail Problem-list audit Code audit Method Age is calculated as of February 1, 2026, matching the CMS reference software, or accepted directly when only age is supplied. Problem-list labels are matched locally to official ICD-10-CM descriptions using exact normalized terms and a small conservative clinical alias set. Ambiguous suggestions are never counted automatically. Confirmed codes are mapped to condition categories, required age/sex edits are applied, HCC hierarchies suppress lower categories, V28 disease and disabled interactions are created, and the selected model coefficients are summed. What this score excludes Normalization, the statutory MA coding-pattern adjustment, frailty, ESRD models, RxHCC, encounter eligibility rules, data-submission acceptance, and plan/payment calculations are outside this tool. New enrollee scores are demographic-only under the CMS model. Source files embedded in this calculator CMS 2026 Midyear/Final Model Software (Python) and 2026 Midyear/Final ICD-10-CM mappings, retrieved from the CMS Risk Adjustment model software page. Model package: CMS_HCC_v28_2026_T_package_v3. Clinician and analytic use only. Verify consequential decisions against current CMS guidance and plan-specific data. CMS 2026 model software and mappings ."}]`);function a(e){return e.normalize(`NFKD`).replace(/[\u0300-\u036f]/g,``).toLowerCase().replace(/[^a-z0-9]+/g,` `).trim()}function o(e,t){let n=a(t).split(` `).filter(Boolean);return n.length?e.map(e=>{let r=a(e.title),i=a(e.text),o=a(e.category);if(!n.every(e=>(r+` `+i+` `+o).includes(e)))return null;let s=n.reduce((e,t)=>e+(r.includes(t)?10:0)+(o.includes(t)?3:0),0)+(r.includes(a(t))?20:0),c=e.text.toLowerCase().indexOf(n[0]),l=Math.max(0,c-55),u=l+185,d=(l?`…`:``)+e.text.slice(l,u)+(u<e.text.length?`…`:``);return{...e,score:s,snippet:d}}).filter(Boolean).sort((e,t)=>t.score-e.score||e.title.localeCompare(t.title)):[]}var s=n();function c(){let[e,t]=(0,r.useState)(``);(0,r.useEffect)(()=>{t(new URLSearchParams(window.location.search).get(`q`)??``)},[]);let n=o(i,e);return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(`form`,{role:`search`,className:`site-search-form`,onSubmit:e=>e.preventDefault(),children:[(0,s.jsx)(`label`,{htmlFor:`site-search-query`,children:`Search this site`}),(0,s.jsxs)(`div`,{className:`site-search-input-row`,children:[(0,s.jsx)(`input`,{id:`site-search-query`,type:`search`,value:e,onChange:e=>t(e.target.value),placeholder:`Try menopause, cholesterol, vaccines, or sleep`,autoFocus:!0,autoComplete:`off`,"aria-describedby":`search-result-count`}),e&&(0,s.jsx)(`button`,{type:`button`,onClick:()=>{t(``),document.getElementById(`site-search-query`)?.focus()},children:`Clear`})]})]}),(0,s.jsx)(`p`,{id:`search-result-count`,role:`status`,"aria-live":`polite`,children:e.trim()?`${n.length} ${n.length===1?`result`:`results`}`:`Find clinical tools, patient guidance, books, and professional resources.`}),e.trim()&&n.length===0&&(0,s.jsx)(`p`,{children:`No matches. Try a shorter phrase, a book title, or a broader topic.`}),(0,s.jsx)(`ul`,{className:`site-search-results`,children:n.map(e=>(0,s.jsx)(`li`,{children:(0,s.jsxs)(`a`,{href:e.url,children:[(0,s.jsx)(`span`,{className:`site-search-category`,children:e.category}),(0,s.jsx)(`h2`,{children:e.title}),(0,s.jsx)(`p`,{children:e.snippet})]})},e.url))})]})}export{c as default};